INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u2-C1','kor',3,1,'u2',2,'단원에서 배울 세 가지 — 문장의 짜임을 알고 바르게 읽고 쓰기 · 글을 유창하게 소리 내어 읽기 · 이야기를 실감 나게 읽기',ARRAY['단원 전체 통합(케이티처 표기 — 단원 도입)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u2-C2','kor',3,1,'u2',2,'분명하게 소리 내어 읽기 — 발표 · 방송 · 동생에게 읽어 줄 때처럼 듣는 사람이 있을 때 글을 소리 내어 읽음 — 또박또박 분명하게 읽으면 뜻이 또렷이 전해짐 · 분명함은 크기가 아니라 또렷함',ARRAY['단원 전체 통합(케이티처 표기 — 단원 도입)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u2-C3','kor',3,1,'u2',2,'듣는 사람에 맞게 읽기 — 발표 = 모두 들리게 · 동생에게 = 다정하고 천천히 · 방송 = 또박또박(한 번만 듣고도 알아듣게) — 듣는 사람과 자리에 따라 목소리 · 빠르기가 달라짐',ARRAY['단원 전체 통합(케이티처 표기 — 단원 도입)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
