INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u2-C31','kor',3,1,'u2',12,'날마다 실천하기 — 단원이 끝나도 책을 읽거나 발표할 때 분명하고 유창하게 읽기를 이어 감',ARRAY['단원 통합 실천(차시 머리 표기 — 번호 없음, W7)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-1-u2-C32','kor',3,1,'u2',12,'뜻이 통하게 두 부분 잇기 — 「누가/무엇이」와 뒷부분은 뜻이 통하게 이어야 함(새가 날아갑니다 · 바다가 넓습니다)',ARRAY['[4국04-03](차시 머리 표기 — 문장의 짜임)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X01','kor',3,'u2',ARRAY['K3-1-u2-C2']::text[],'목소리만 크면 분명하게 읽은 것이라고 여겨 낱말을 뭉개어 읽는다','크기보다 또렷함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X02','kor',3,'u2',ARRAY['K3-1-u2-C2']::text[],'웅얼거리거나 소리 없이 눈으로만 보아도 소리 내어 읽은 것과 같다고 여긴다','듣는 사람이 알아듣게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X03','kor',3,'u2',ARRAY['K3-1-u2-C1','K3-1-u2-C3']::text[],'듣는 사람과 자리를 생각하지 않고 언제나 똑같이 읽는다','누가 듣나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X04','kor',3,'u2',ARRAY['K3-1-u2-C4']::text[],'뒷부분만 있어도 문장이라고 여긴다(「뛰어갑니다.」)','누가 했나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X05','kor',3,'u2',ARRAY['K3-1-u2-C4','K3-1-u2-C32']::text[],'「누가/무엇이」와 뒷부분을 뜻이 통하지 않게 잇는다(새가 맛있습니다)','뜻이 통하나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X06','kor',3,'u2',ARRAY['K3-1-u2-C5','K3-1-u2-C6']::text[],'움직임(어찌하다)과 상태(어떠하다)를 헷갈린다(빨갛습니다를 움직임으로)','몸으로 해 볼 수 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X07','kor',3,'u2',ARRAY['K3-1-u2-C6','K3-1-u2-C7']::text[],'상태(어떠하다)와 무엇인지(무엇이다)를 헷갈린다','무엇인지 알려 주나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X08','kor',3,'u2',ARRAY['K3-1-u2-C5','K3-1-u2-C7']::text[],'무엇이다를 움직임으로, 움직임을 무엇이다로 바꾸어 안다','움직임일까, 무엇일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X09','kor',3,'u2',ARRAY['K3-1-u2-C8']::text[],'「누가/무엇이」가 끝나지 않은 엉뚱한 곳에서 문장을 나눈다','누가/무엇이는 어디까지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X10','kor',3,'u2',ARRAY['K3-1-u2-C9']::text[],'문장은 길게 이어 붙일수록 좋다고 여긴다','두 부분이 또렷하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X11','kor',3,'u2',ARRAY['K3-1-u2-C10','K3-1-u2-C12']::text[],'∨ 를 낱말 가운데에 둔다(사람 ∨ 들은)','낱말은 가르지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X12','kor',3,'u2',ARRAY['K3-1-u2-C12']::text[],'∨ 를 많이 둘수록 잘 띄어 읽는 것이라고 여겨 낱말마다 끊는다','뜻이 갈리는 곳에만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X13','kor',3,'u2',ARRAY['K3-1-u2-C10','K3-1-u2-C11']::text[],'∨ 와 ∨∨ 의 쉬는 정도나 자리를 바꾸어 안다','조금 / 조금 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X14','kor',3,'u2',ARRAY['K3-1-u2-C13']::text[],'띄어 읽기는 뜻과 상관없어 아무 데서나 쉬어도 같다고 여긴다','쉬는 곳이 뜻을 바꿔요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X15','kor',3,'u2',ARRAY['K3-1-u2-C14']::text[],'글을 쓸 때 짜임을 생각하지 않아 「누가/무엇이」를 빠뜨리거나 낱말만 늘어놓는다','두 부분을 갖춰 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X16','kor',3,'u2',ARRAY['K3-1-u2-C15','K3-1-u2-C16']::text[],'빨리 읽을수록 유창하게 읽는 것이라고 여긴다','빠르기 겨루기가 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X17','kor',3,'u2',ARRAY['K3-1-u2-C16']::text[],'한 글자씩 아주 느리게 뚝뚝 끊어 읽어야 분명하다고 여긴다','너무 느려도 뜻이 끊겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X18','kor',3,'u2',ARRAY['K3-1-u2-C17']::text[],'쉼표 · 마침표를 무시하거나 쉬는 정도를 바꾸어 읽는다','쉼표 조금, 마침표 조금 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X19','kor',3,'u2',ARRAY['K3-1-u2-C17']::text[],'물음표가 있는 문장의 끝을 올려 읽어야 함을 모른다','묻는 말은 끝을 올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X20','kor',3,'u2',ARRAY['K3-1-u2-C18']::text[],'모르는 낱말이나 글자는 건너뛰어도 된다고 여긴다','건너뛰면 뜻이 사라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X21','kor',3,'u2',ARRAY['K3-1-u2-C19']::text[],'뜻은 생각하지 않고 소리만 내면 유창하게 읽은 것이라고 여긴다','무슨 뜻인지 생각하며') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X22','kor',3,'u2',ARRAY['K3-1-u2-C20','K3-1-u2-C25']::text[],'이야기를 처음부터 끝까지 같은 목소리 · 같은 표정으로 읽는다','마음이 바뀌면 목소리도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X23','kor',3,'u2',ARRAY['K3-1-u2-C21']::text[],'인물의 마음을 반대로 짐작한다(아쉬워 작게 말함 = 신남)','인물이 어떻게 말했나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X24','kor',3,'u2',ARRAY['K3-1-u2-C22','K3-1-u2-C23']::text[],'준언어(목소리)와 비언어(표정 · 몸짓)를 바꾸어 안다','목소리일까, 몸일까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X25','kor',3,'u2',ARRAY['K3-1-u2-C24']::text[],'인물의 마음과 어울리지 않는 목소리 · 표정을 고른다','그때 마음에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X26','kor',3,'u2',ARRAY['K3-1-u2-C26']::text[],'실감 나게 읽으려면 언제나 크게 소리쳐야 한다고 여긴다','크기보다 어울림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X27','kor',3,'u2',ARRAY['K3-1-u2-C27']::text[],'실감 나게 읽기는 연기 잘하는 사람만 하는 것이라고 여겨 해 보지 않는다','한 가지만 바꿔 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X28','kor',3,'u2',ARRAY['K3-1-u2-C28']::text[],'읽을 글 고르기 · ∨ 표시 · 연습 없이 바로 발표한다','고르고, 표시하고, 연습') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X29','kor',3,'u2',ARRAY['K3-1-u2-C29']::text[],'발표회를 잘 읽는 사람만 나가는 겨루기로 여긴다','함께 나누는 시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X30','kor',3,'u2',ARRAY['K3-1-u2-C30']::text[],'친구의 읽기를 끝까지 듣지 않거나 흠부터 잡고 놀린다','잘한 점 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X31','kor',3,'u2',ARRAY['K3-1-u2-C31']::text[],'단원이 끝나면 배운 읽기도 끝이라고 여긴다','날마다 이어 가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-1-u2-X32','kor',3,'u2',ARRAY['K3-1-u2-C21']::text[],'인물이 한 말과 행동이 아니라 내 기분이나 상관없는 것으로 마음을 짐작한다','근거는 이야기 속에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
