INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L02_challenge#6','kor',3,1,'u2','L02','g3_1_kor_u2_L02_challenge','lesson_challenge','K3-1-u2-C9',3,'mc','auto','좋은 문장에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u2-X10','K3-1-u2-X04']::text[],false,'{"seq":6,"concept":"K3-1-u2-C9","difficulty":3,"kind":"mc","stem":"좋은 문장에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"누가 무엇을 하는지 두 부분이 또렷한 문장이 좋아요.","correct":true},{"t":"길게 이어 붙일수록 좋아요.","mis":"K3-1-u2-X10"},{"t":"뒷부분만 있어도 좋아요.","mis":"K3-1-u2-X04"},{"t":"낱말을 많이 넣을수록 언제나 좋아요.","mis":"K3-1-u2-X10"}],"explanation":["길이가 아니라","두 부분이","또렷하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L02_challenge#7','kor',3,1,'u2','L02','g3_1_kor_u2_L02_challenge','lesson_challenge','K3-1-u2-C8',3,'mc','auto','「태민이는 앵무새 초롱이를 키웁니다.」를 두 부분으로 바르게 나눈 것은 무엇일까요?',ARRAY['K3-1-u2-X09']::text[],false,'{"seq":7,"concept":"K3-1-u2-C8","difficulty":3,"kind":"mc","stem":"「태민이는 앵무새 초롱이를 키웁니다.」를 두 부분으로 바르게 나눈 것은 무엇일까요?","options":[{"t":"태민이는 / 앵무새 초롱이를 키웁니다.","correct":true},{"t":"태민이는 앵무새 / 초롱이를 키웁니다.","mis":"K3-1-u2-X09"},{"t":"태민이는 앵무새 초롱이를 / 키웁니다.","mis":"K3-1-u2-X09"},{"t":"태민 / 이는 앵무새 초롱이를 키웁니다.","mis":"K3-1-u2-X09"}],"explanation":["누가?","태민이는","나머지는 한 덩어리"],"asset":{"type":"passage","lines":["태민이는 앵무새 초롱이를 키웁니다.","초롱이는 작습니다.","초롱이의 깃털이 부드럽습니다.","초롱이가 노래합니다.","태민이가 손뼉을 칩니다.","초롱이는 태민이의 친구입니다."],"title":"태민이와 앵무새 초롱이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L02_challenge#8','kor',3,1,'u2','L02','g3_1_kor_u2_L02_challenge','lesson_challenge','K3-1-u2-C5',4,'essay','teacher','「태민이와 앵무새 초롱이」에서 뒷부분이 어찌하다 · 어떠하다 · 무엇이다인 문장을 하나씩 찾아 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u2-C5","difficulty":4,"kind":"essay","stem":"「태민이와 앵무새 초롱이」에서 뒷부분이 어찌하다 · 어떠하다 · 무엇이다인 문장을 하나씩 찾아 쓰세요.","answer_guide":{"answer":"예: 어찌하다 — 초롱이가 노래합니다. 어떠하다 — 초롱이는 작습니다. 무엇이다 — 초롱이는 태민이의 친구입니다.","scoring_points":["어찌하다 문장을 찾았는가","어떠하다 문장을 찾았는가","무엇이다 문장을 찾았는가"]},"explanation":["움직임","상태","무엇인지"],"asset":{"type":"passage","lines":["태민이는 앵무새 초롱이를 키웁니다.","초롱이는 작습니다.","초롱이의 깃털이 부드럽습니다.","초롱이가 노래합니다.","태민이가 손뼉을 칩니다.","초롱이는 태민이의 친구입니다."],"title":"태민이와 앵무새 초롱이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L02_challenge#9','kor',3,1,'u2','L02','g3_1_kor_u2_L02_challenge','lesson_challenge','K3-1-u2-C4',4,'essay','teacher','「뛰어갑니다.」를 문장이 되게 고쳐 쓰고, 왜 고쳐야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u2-C4","difficulty":4,"kind":"essay","stem":"「뛰어갑니다.」를 문장이 되게 고쳐 쓰고, 왜 고쳐야 하는지 쓰세요.","answer_guide":{"answer":"예: 강아지가 뛰어갑니다. 「뛰어갑니다.」만 있으면 누가 뛰어가는지 알 수 없어서 「누가/무엇이」를 넣어야 한다.","scoring_points":["「누가/무엇이」를 넣어 고쳤는가","뜻이 통하는가","고친 까닭을 썼는가"]},"explanation":["누가","뛰어가나요?","앞부분 넣기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L02_challenge#10','kor',3,1,'u2','L02','g3_1_kor_u2_L02_challenge','lesson_challenge','K3-1-u2-C3',4,'essay','teacher','「하늘이 파랗습니다.」를 교실에서 발표할 때와 동생에게 읽어 줄 때 각각 어떻게 읽을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u2-C3","difficulty":4,"kind":"essay","stem":"「하늘이 파랗습니다.」를 교실에서 발표할 때와 동생에게 읽어 줄 때 각각 어떻게 읽을지 쓰세요.","answer_guide":{"answer":"예: 발표할 때는 교실 뒤까지 들리게 또박또박 읽는다. 동생에게는 다정한 목소리로 조금 천천히 읽어 준다.","scoring_points":["발표할 때 읽는 방법을 썼는가","동생에게 읽어 줄 때 방법을 썼는가","듣는 사람에 따라 달라짐이 드러나는가"]},"explanation":["발표","동생","듣는 사람"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
