INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L05_basic#6','kor',3,1,'u2','L05','g3_1_kor_u2_L05_basic','lesson_basic','K3-1-u2-C12',2,'mc','auto','바르게 띄어 읽은 것은 무엇일까요?',ARRAY['K3-1-u2-X11','K3-1-u2-X12']::text[],false,'{"seq":6,"concept":"K3-1-u2-C12","difficulty":2,"kind":"mc","stem":"바르게 띄어 읽은 것은 무엇일까요?","options":[{"t":"아이들이 ∨ 언덕에 오릅니다.","correct":true},{"t":"아이 ∨ 들이 언덕에 오릅니다.","mis":"K3-1-u2-X11"},{"t":"아이들이 ∨ 언 ∨ 덕에 ∨ 오 ∨ 릅니다.","mis":"K3-1-u2-X12"},{"t":"아이들이 언덕에 오릅 ∨ 니다.","mis":"K3-1-u2-X11"}],"explanation":["누가?","아이들이","다음에 ∨"],"asset":{"type":"passage","lines":["연날리기는 겨울 놀이입니다.","아이들이 언덕에 오릅니다.","바람이 차갑습니다.","연이 하늘 높이 날아갑니다.","우리는 실을 천천히 풉니다."],"title":"연날리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L05_basic#7','kor',3,1,'u2','L05','g3_1_kor_u2_L05_basic','lesson_basic','K3-1-u2-C13',2,'match','auto','「연날리기」의 문장과 그 짜임을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-1-u2-C13","difficulty":2,"kind":"match","stem":"「연날리기」의 문장과 그 짜임을 알맞게 이으세요.","pairs":[{"l":"연이 하늘 높이 날아갑니다.","r":"어찌하다"},{"l":"바람이 차갑습니다.","r":"어떠하다"},{"l":"연날리기는 겨울 놀이입니다.","r":"무엇이다"}],"mis":"K3-1-u2-X06","explanation":["날아가기 = 움직임","차가움 = 상태","놀이 = 무엇"],"asset":{"type":"passage","lines":["연날리기는 겨울 놀이입니다.","아이들이 언덕에 오릅니다.","바람이 차갑습니다.","연이 하늘 높이 날아갑니다.","우리는 실을 천천히 풉니다."],"title":"연날리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
