INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L05_challenge#6','kor',3,1,'u2','L05','g3_1_kor_u2_L05_challenge','lesson_challenge','K3-1-u2-C11',3,'mc','auto','「연날리기는 ∨ 겨울 놀이입니다. ∨∨」를 읽는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X13','K3-1-u2-X14']::text[],false,'{"seq":6,"concept":"K3-1-u2-C11","difficulty":3,"kind":"mc","stem":"「연날리기는 ∨ 겨울 놀이입니다. ∨∨」를 읽는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"「연날리기는」 다음에 조금 쉬고, 「놀이입니다.」 다음에 조금 더 쉬어요.","correct":true},{"t":"「연날리기는」 다음에 조금 더 쉬고, 「놀이입니다.」 다음에 조금만 쉬어요.","mis":"K3-1-u2-X13"},{"t":"두 표시 모두 쉬지 않고 붙여 읽어요.","mis":"K3-1-u2-X14"},{"t":"표시가 있는 곳의 낱말을 빼고 읽어요.","mis":"K3-1-u2-X14"}],"explanation":["∨ 조금","∨∨ 조금 더","쉬어 읽기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L05_challenge#7','kor',3,1,'u2','L05','g3_1_kor_u2_L05_challenge','lesson_challenge','K3-1-u2-C12',3,'mc','auto','「강아지가 꼬리를 흔듭니다.」를 바르게 띄어 읽은 것은 무엇일까요?',ARRAY['K3-1-u2-X11','K3-1-u2-X12']::text[],false,'{"seq":7,"concept":"K3-1-u2-C12","difficulty":3,"kind":"mc","stem":"「강아지가 꼬리를 흔듭니다.」를 바르게 띄어 읽은 것은 무엇일까요?","options":[{"t":"강아지가 ∨ 꼬리를 흔듭니다.","correct":true},{"t":"강아지 ∨ 가 꼬리를 흔듭니다.","mis":"K3-1-u2-X11"},{"t":"강아지가 꼬리를 흔 ∨ 듭니다.","mis":"K3-1-u2-X11"},{"t":"강 ∨ 아지가 ∨ 꼬 ∨ 리를 흔듭니다.","mis":"K3-1-u2-X12"}],"explanation":["누가?","강아지가","다음에 ∨"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L05_challenge#8','kor',3,1,'u2','L05','g3_1_kor_u2_L05_challenge','lesson_challenge','K3-1-u2-C14',4,'essay','teacher','내가 좋아하는 놀이를 「누가/무엇이 + 어찌하다」 짜임으로 한 문장 쓰고, 알맞은 곳에 ∨와 ∨∨를 표시하세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u2-C14","difficulty":4,"kind":"essay","stem":"내가 좋아하는 놀이를 「누가/무엇이 + 어찌하다」 짜임으로 한 문장 쓰고, 알맞은 곳에 ∨와 ∨∨를 표시하세요.","answer_guide":{"answer":"예: 나는 ∨ 친구와 술래잡기를 합니다. ∨∨","scoring_points":["두 부분을 갖춘 문장인가","「누가/무엇이」 다음에 ∨를 두었는가","문장 끝에 ∨∨를 두었는가"]},"explanation":["누가","어찌하다","∨ · ∨∨"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L05_challenge#9','kor',3,1,'u2','L05','g3_1_kor_u2_L05_challenge','lesson_challenge','K3-1-u2-C10',4,'essay','teacher','「연날리기」에서 두 문장을 골라 ∨와 ∨∨를 알맞게 표시해 옮겨 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u2-C10","difficulty":4,"kind":"essay","stem":"「연날리기」에서 두 문장을 골라 ∨와 ∨∨를 알맞게 표시해 옮겨 쓰세요.","answer_guide":{"answer":"예: 아이들이 ∨ 언덕에 오릅니다. ∨∨ 바람이 ∨ 차갑습니다. ∨∨","scoring_points":["두 문장을 옮겨 썼는가","「누가/무엇이」 다음에 ∨를 두었는가","문장 끝에 ∨∨를 두었는가"]},"explanation":["누가/무엇이 다음","문장 끝","표시"],"asset":{"type":"passage","lines":["연날리기는 겨울 놀이입니다.","아이들이 언덕에 오릅니다.","바람이 차갑습니다.","연이 하늘 높이 날아갑니다.","우리는 실을 천천히 풉니다."],"title":"연날리기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L05_challenge#10','kor',3,1,'u2','L05','g3_1_kor_u2_L05_challenge','lesson_challenge','K3-1-u2-C13',4,'essay','teacher','∨를 낱말 가운데에 두면 안 되는 까닭을 예를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u2-C13","difficulty":4,"kind":"essay","stem":"∨를 낱말 가운데에 두면 안 되는 까닭을 예를 들어 쓰세요.","answer_guide":{"answer":"예: 「바람 ∨ 이 차갑습니다.」처럼 낱말 가운데를 가르면 「바람이」라는 낱말이 끊겨 뜻이 흐려진다. 「바람이 ∨ 차갑습니다.」처럼 「누가/무엇이」가 끝나는 곳에서 쉬어야 뜻이 또렷하다.","scoring_points":["낱말을 가른 예를 들었는가","뜻이 흐려진다는 까닭을 썼는가","바르게 고친 읽기를 썼는가"]},"explanation":["낱말 가운데","뜻이 흐려져요","바른 자리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
