INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_basic#7','kor',3,1,'u2','L07','g3_1_kor_u2_L07_basic','lesson_basic','K3-1-u2-C18',2,'mc','auto','글을 읽다가 모르는 낱말이 나오면 어떻게 할까요?',ARRAY['K3-1-u2-X20','K3-1-u2-X21']::text[],false,'{"seq":7,"concept":"K3-1-u2-C18","difficulty":2,"kind":"mc","stem":"글을 읽다가 모르는 낱말이 나오면 어떻게 할까요?","options":[{"t":"건너뛰지 말고 또박또박 읽은 뒤 뜻을 알아봐요.","correct":true},{"t":"건너뛰고 빨리 읽어요.","mis":"K3-1-u2-X20"},{"t":"비슷한 아무 낱말로 바꾸어 읽어요.","mis":"K3-1-u2-X21"},{"t":"모르는 낱말이 나온 문장은 통째로 빼요.","mis":"K3-1-u2-X20"}],"explanation":["건너뛰면","뜻이 사라져요","빠짐없이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_basic#8','kor',3,1,'u2','L07','g3_1_kor_u2_L07_basic','lesson_basic','K3-1-u2-C17',2,'match','auto','문장 부호와 읽는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u2-C17","difficulty":2,"kind":"match","stem":"문장 부호와 읽는 방법을 알맞게 이으세요.","pairs":[{"l":"쉼표 ,","r":"조금 쉬어 읽기"},{"l":"마침표 .","r":"조금 더 쉬어 읽기"},{"l":"물음표 ?","r":"끝을 올려 읽기"}],"mis":"K3-1-u2-X18","explanation":["쉼표 조금","마침표 조금 더","물음표 끝 올리기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_basic#9','kor',3,1,'u2','L07','g3_1_kor_u2_L07_basic','lesson_basic','K3-1-u2-C19',2,'mc','auto','「도서실을 함께 쓰려면」이 말하려는 것은 무엇일까요?',ARRAY['K3-1-u2-X21','K3-1-u2-X16']::text[],false,'{"seq":9,"concept":"K3-1-u2-C19","difficulty":2,"kind":"mc","stem":"「도서실을 함께 쓰려면」이 말하려는 것은 무엇일까요?","options":[{"t":"도서실에서 지킬 일을 지키면 모두 즐겁게 읽을 수 있다","correct":true},{"t":"도서실에는 가지 않는 것이 좋다","mis":"K3-1-u2-X21"},{"t":"책은 빨리 읽을수록 좋다","mis":"K3-1-u2-X16"},{"t":"도서실에서는 마음껏 뛰어도 된다","mis":"K3-1-u2-X21"}],"explanation":["지킬 일","모두","즐겁게"],"asset":{"type":"passage","lines":["도서실에서는 발소리를 줄이고 조용히 걸어요.","다 읽은 책은 제자리에 꽂아요.","책장을 넘길 때에는 천천히, 살살 넘겨요.","책을 깨끗하게 보면 어떨까요?","그러면 모두가 즐겁게 읽을 수 있어요."],"title":"도서실을 함께 쓰려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_basic#10','kor',3,1,'u2','L07','g3_1_kor_u2_L07_basic','lesson_basic','K3-1-u2-C18',3,'mc','auto','「도서실을 함께 쓰려면」을 친구들 앞에서 읽을 때 가장 알맞은 방법은 무엇일까요?',ARRAY['K3-1-u2-X20','K3-1-u2-X18','K3-1-u2-X16']::text[],false,'{"seq":10,"concept":"K3-1-u2-C18","difficulty":3,"kind":"mc","stem":"「도서실을 함께 쓰려면」을 친구들 앞에서 읽을 때 가장 알맞은 방법은 무엇일까요?","options":[{"t":"부호에 맞게 쉬며 뜻을 생각해 빠짐없이 읽는다","correct":true},{"t":"어려운 낱말은 건너뛰며 읽는다","mis":"K3-1-u2-X20"},{"t":"쉼표 · 마침표와 상관없이 아무 데서나 끊어 읽는다","mis":"K3-1-u2-X18"},{"t":"뜻은 몰라도 가장 빠르게 읽는다","mis":"K3-1-u2-X16"}],"explanation":["부호","뜻","빠짐없이"],"asset":{"type":"passage","lines":["도서실에서는 발소리를 줄이고 조용히 걸어요.","다 읽은 책은 제자리에 꽂아요.","책장을 넘길 때에는 천천히, 살살 넘겨요.","책을 깨끗하게 보면 어떨까요?","그러면 모두가 즐겁게 읽을 수 있어요."],"title":"도서실을 함께 쓰려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#1','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C17',2,'mc','auto','「책을 깨끗하게 보면 어떨까요?」는 어떻게 읽으면 좋을까요?',ARRAY['K3-1-u2-X19','K3-1-u2-X20','K3-1-u2-X18']::text[],false,'{"seq":1,"concept":"K3-1-u2-C17","difficulty":2,"kind":"mc","stem":"「책을 깨끗하게 보면 어떨까요?」는 어떻게 읽으면 좋을까요?","options":[{"t":"끝을 올려 묻듯이 읽어요.","correct":true},{"t":"끝을 내려 화난 듯이 읽어요.","mis":"K3-1-u2-X19"},{"t":"「어떨까요」를 빼고 읽어요.","mis":"K3-1-u2-X20"},{"t":"쉬지 않고 다음 문장까지 붙여 읽어요.","mis":"K3-1-u2-X18"}],"explanation":["물음표","묻는 말","끝을 올려"],"asset":{"type":"passage","lines":["도서실에서는 발소리를 줄이고 조용히 걸어요.","다 읽은 책은 제자리에 꽂아요.","책장을 넘길 때에는 천천히, 살살 넘겨요.","책을 깨끗하게 보면 어떨까요?","그러면 모두가 즐겁게 읽을 수 있어요."],"title":"도서실을 함께 쓰려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#2','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C15',2,'mc','auto','유창하게 읽기에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u2-X16','K3-1-u2-X20','K3-1-u2-X17']::text[],false,'{"seq":2,"concept":"K3-1-u2-C15","difficulty":2,"kind":"mc","stem":"유창하게 읽기에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"빠르기 겨루기가 아니라 듣는 사람이 뜻을 알아듣게 읽는 거예요.","correct":true},{"t":"가장 빨리 읽는 사람이 가장 유창해요.","mis":"K3-1-u2-X16"},{"t":"글자를 조금 빼도 술술 읽히면 유창해요.","mis":"K3-1-u2-X20"},{"t":"한 글자씩 뚝뚝 끊어야 유창해요.","mis":"K3-1-u2-X17"}],"explanation":["겨루기가 아니라","듣는 사람이","알아듣게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#3','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C17',3,'mc','auto','「책장을 넘길 때에는 천천히, 살살 넘겨요.」를 바르게 읽는 방법은 무엇일까요?',ARRAY['K3-1-u2-X18','K3-1-u2-X19']::text[],false,'{"seq":3,"concept":"K3-1-u2-C17","difficulty":3,"kind":"mc","stem":"「책장을 넘길 때에는 천천히, 살살 넘겨요.」를 바르게 읽는 방법은 무엇일까요?","options":[{"t":"「천천히,」에서 조금 쉬고, 「넘겨요.」 다음에서 조금 더 쉬어요.","correct":true},{"t":"「천천히,」에서 오래 쉬고, 「넘겨요.」 다음에서는 쉬지 않아요.","mis":"K3-1-u2-X18"},{"t":"쉼표는 없는 것처럼 붙여 읽어요.","mis":"K3-1-u2-X18"},{"t":"끝을 올려 묻듯이 읽어요.","mis":"K3-1-u2-X19"}],"explanation":["쉼표 조금","마침표 조금 더","부호에 맞게"],"asset":{"type":"passage","lines":["도서실에서는 발소리를 줄이고 조용히 걸어요.","다 읽은 책은 제자리에 꽂아요.","책장을 넘길 때에는 천천히, 살살 넘겨요.","책을 깨끗하게 보면 어떨까요?","그러면 모두가 즐겁게 읽을 수 있어요."],"title":"도서실을 함께 쓰려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#4','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C16',3,'mc','auto','은솔이는 1분 동안 글자를 가장 많이 읽으려고 숨도 쉬지 않고 읽어요. 은솔이에게 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X16','K3-1-u2-X20','K3-1-u2-X17']::text[],false,'{"seq":4,"concept":"K3-1-u2-C16","difficulty":3,"kind":"mc","stem":"은솔이는 1분 동안 글자를 가장 많이 읽으려고 숨도 쉬지 않고 읽어요. 은솔이에게 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「듣는 사람이 알아듣게 알맞은 빠르기로 읽어 보자.」","correct":true},{"t":"「더 빨리 읽으면 1등이야!」","mis":"K3-1-u2-X16"},{"t":"「모르는 낱말은 건너뛰면 더 빨라.」","mis":"K3-1-u2-X20"},{"t":"「한 글자씩 아주 느리게 읽어.」","mis":"K3-1-u2-X17"}],"explanation":["빠르기 겨루기?","알맞은 빠르기","듣는 사람"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#5','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C19',3,'mc','auto','글의 뜻을 생각하며 읽어야 하는 까닭은 무엇일까요?',ARRAY['K3-1-u2-X21','K3-1-u2-X16','K3-1-u2-X18']::text[],false,'{"seq":5,"concept":"K3-1-u2-C19","difficulty":3,"kind":"mc","stem":"글의 뜻을 생각하며 읽어야 하는 까닭은 무엇일까요?","options":[{"t":"어디서 쉬고 무엇을 힘주어 읽을지 알 수 있어 뜻이 잘 전해져서","correct":true},{"t":"뜻은 몰라도 소리만 내면 똑같아서","mis":"K3-1-u2-X21"},{"t":"뜻을 생각하면 언제나 느려져서 나빠서","mis":"K3-1-u2-X16"},{"t":"뜻은 쉼표와 마침표만 보면 저절로 알 수 있어서","mis":"K3-1-u2-X18"}],"explanation":["뜻을 알아야","쉬고 힘줄 곳","잘 전해져요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#6','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C18',3,'mc','auto','도윤이는 「다 읽은 책은 제자리에 꽂아요.」를 「다 읽은 책은 꽂아요.」로 읽었어요. 무엇이 문제일까요?',ARRAY['K3-1-u2-X20','K3-1-u2-X16','K3-1-u2-X21']::text[],false,'{"seq":6,"concept":"K3-1-u2-C18","difficulty":3,"kind":"mc","stem":"도윤이는 「다 읽은 책은 제자리에 꽂아요.」를 「다 읽은 책은 꽂아요.」로 읽었어요. 무엇이 문제일까요?","options":[{"t":"「제자리에」를 빠뜨려 어디에 꽂는지 뜻이 사라졌어요.","correct":true},{"t":"빠뜨려도 술술 읽혀서 더 잘 읽었어요.","mis":"K3-1-u2-X20"},{"t":"빠르게 읽어서 유창했어요.","mis":"K3-1-u2-X16"},{"t":"한 낱말쯤은 빠져도 뜻이 똑같아요.","mis":"K3-1-u2-X21"}],"explanation":["빠뜨린 낱말","제자리에","뜻이 사라져요"],"asset":{"type":"passage","lines":["도서실에서는 발소리를 줄이고 조용히 걸어요.","다 읽은 책은 제자리에 꽂아요.","책장을 넘길 때에는 천천히, 살살 넘겨요.","책을 깨끗하게 보면 어떨까요?","그러면 모두가 즐겁게 읽을 수 있어요."],"title":"도서실을 함께 쓰려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#7','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C15',3,'mc','auto','유창하게 읽었는지 스스로 점검하는 물음으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X16','K3-1-u2-X20','K3-1-u2-X17']::text[],false,'{"seq":7,"concept":"K3-1-u2-C15","difficulty":3,"kind":"mc","stem":"유창하게 읽었는지 스스로 점검하는 물음으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「뜻을 생각하며, 알맞은 빠르기로, 부호에 맞게 쉬어 읽었나요?」","correct":true},{"t":"「친구보다 더 빨리 읽었나요?」","mis":"K3-1-u2-X16"},{"t":"「어려운 낱말을 잘 건너뛰었나요?」","mis":"K3-1-u2-X20"},{"t":"「한 글자씩 또박또박 끊어서 아주 느리게 읽었나요?」","mis":"K3-1-u2-X17"}],"explanation":["뜻","빠르기","부호"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#8','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C17',4,'essay','teacher','「도서실을 함께 쓰려면」의 셋째 줄과 넷째 줄을 읽을 때 쉬는 곳과 끝을 올릴 곳을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u2-C17","difficulty":4,"kind":"essay","stem":"「도서실을 함께 쓰려면」의 셋째 줄과 넷째 줄을 읽을 때 쉬는 곳과 끝을 올릴 곳을 쓰세요.","answer_guide":{"answer":"예: 셋째 줄은 「천천히,」의 쉼표에서 조금 쉬고, 「넘겨요.」의 마침표 뒤에서 조금 더 쉰다. 넷째 줄 「어떨까요?」는 물음표가 있으니 끝을 올려 읽는다.","scoring_points":["쉼표에서 조금 쉰다고 썼는가","마침표 뒤에서 조금 더 쉰다고 썼는가","물음표 문장의 끝을 올린다고 썼는가"]},"explanation":["쉼표","마침표","물음표"],"asset":{"type":"passage","lines":["도서실에서는 발소리를 줄이고 조용히 걸어요.","다 읽은 책은 제자리에 꽂아요.","책장을 넘길 때에는 천천히, 살살 넘겨요.","책을 깨끗하게 보면 어떨까요?","그러면 모두가 즐겁게 읽을 수 있어요."],"title":"도서실을 함께 쓰려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#9','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C16',4,'essay','teacher','글을 너무 빠르게 읽을 때와 너무 느리게 읽을 때 생기는 일을 각각 쓰고, 알맞은 빠르기란 무엇인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u2-C16","difficulty":4,"kind":"essay","stem":"글을 너무 빠르게 읽을 때와 너무 느리게 읽을 때 생기는 일을 각각 쓰고, 알맞은 빠르기란 무엇인지 쓰세요.","answer_guide":{"answer":"예: 너무 빠르면 듣는 사람이 알아듣기 어렵다. 너무 느리면 뚝뚝 끊겨 지루하고 뜻이 이어지지 않는다. 알맞은 빠르기는 듣는 사람이 편하게 알아들을 수 있는 빠르기이다.","scoring_points":["너무 빠를 때를 썼는가","너무 느릴 때를 썼는가","알맞은 빠르기를 설명했는가"]},"explanation":["빠르면","느리면","알맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L07_challenge#10','kor',3,1,'u2','L07','g3_1_kor_u2_L07_challenge','lesson_challenge','K3-1-u2-C19',4,'essay','teacher','「도서실을 함께 쓰려면」이 말하려는 것을 한 문장으로 쓰고, 그 뜻을 살리려고 힘주어 읽을 낱말을 하나 골라 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u2-C19","difficulty":4,"kind":"essay","stem":"「도서실을 함께 쓰려면」이 말하려는 것을 한 문장으로 쓰고, 그 뜻을 살리려고 힘주어 읽을 낱말을 하나 골라 까닭을 쓰세요.","answer_guide":{"answer":"예: 도서실에서 지킬 일을 지키면 모두가 즐겁게 읽을 수 있다. 「모두가」를 힘주어 읽겠다. 혼자가 아니라 함께 쓰는 곳이라는 뜻이 잘 전해지기 때문이다.","scoring_points":["말하려는 것을 한 문장으로 썼는가","힘주어 읽을 낱말을 골랐는가","까닭이 글의 뜻과 이어지는가"]},"explanation":["말하려는 것","힘줄 낱말","까닭"],"asset":{"type":"passage","lines":["도서실에서는 발소리를 줄이고 조용히 걸어요.","다 읽은 책은 제자리에 꽂아요.","책장을 넘길 때에는 천천히, 살살 넘겨요.","책을 깨끗하게 보면 어떨까요?","그러면 모두가 즐겁게 읽을 수 있어요."],"title":"도서실을 함께 쓰려면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_basic#1','kor',3,1,'u2','L09','g3_1_kor_u2_L09_basic','lesson_basic','K3-1-u2-C20',1,'mc','auto','이야기를 실감 나게 읽는다는 것은 무엇일까요?',ARRAY['K3-1-u2-X22','K3-1-u2-X26']::text[],false,'{"seq":1,"concept":"K3-1-u2-C20","difficulty":1,"kind":"mc","stem":"이야기를 실감 나게 읽는다는 것은 무엇일까요?","options":[{"t":"인물의 마음을 짐작해 목소리와 표정으로 살려 읽는 것","correct":true},{"t":"처음부터 끝까지 같은 목소리로 읽는 것","mis":"K3-1-u2-X22"},{"t":"무조건 가장 크게 소리치며 읽는 것","mis":"K3-1-u2-X26"},{"t":"표정 없이 글자만 또박또박 읽는 것","mis":"K3-1-u2-X22"}],"explanation":["인물의 마음","목소리 · 표정","살려 읽기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_basic#2','kor',3,1,'u2','L09','g3_1_kor_u2_L09_basic','lesson_basic','K3-1-u2-C22',1,'mc','auto','준언어로 나타내는 것을 모은 것은 무엇일까요?',ARRAY['K3-1-u2-X24']::text[],false,'{"seq":2,"concept":"K3-1-u2-C22","difficulty":1,"kind":"mc","stem":"준언어로 나타내는 것을 모은 것은 무엇일까요?","options":[{"t":"목소리의 크기 · 빠르기 · 높낮이","correct":true},{"t":"얼굴 표정과 손짓","mis":"K3-1-u2-X24"},{"t":"글자의 크기와 색","mis":"K3-1-u2-X24"},{"t":"어깨와 고개의 움직임","mis":"K3-1-u2-X24"}],"explanation":["준언어","목소리","크기 · 빠르기 · 높낮이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
