INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_basic#4','kor',3,1,'u2','L09','g3_1_kor_u2_L09_basic','lesson_basic','K3-1-u2-C24',1,'mc','auto','기쁜 마음을 읽을 때 어울리는 목소리는 무엇일까요?',ARRAY['K3-1-u2-X25']::text[],false,'{"seq":4,"concept":"K3-1-u2-C24","difficulty":1,"kind":"mc","stem":"기쁜 마음을 읽을 때 어울리는 목소리는 무엇일까요?","options":[{"t":"밝고 신나는 목소리","correct":true},{"t":"느리고 낮은 목소리","mis":"K3-1-u2-X25"},{"t":"화난 목소리","mis":"K3-1-u2-X25"},{"t":"졸린 목소리","mis":"K3-1-u2-X25"}],"explanation":["기쁨","밝게","신나게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_basic#5','kor',3,1,'u2','L09','g3_1_kor_u2_L09_basic','lesson_basic','K3-1-u2-C21',2,'mc','auto','「이사 가는 날」에서 하람이가 텅 빈 방을 둘러보며 작게 말할 때의 마음은 무엇일까요?',ARRAY['K3-1-u2-X23','K3-1-u2-X32']::text[],false,'{"seq":5,"concept":"K3-1-u2-C21","difficulty":2,"kind":"mc","stem":"「이사 가는 날」에서 하람이가 텅 빈 방을 둘러보며 작게 말할 때의 마음은 무엇일까요?","options":[{"t":"아쉽고 섭섭한 마음","correct":true},{"t":"신나고 들뜬 마음","mis":"K3-1-u2-X23"},{"t":"화가 난 마음","mis":"K3-1-u2-X23"},{"t":"내가 오늘 즐거우니 즐거운 마음","mis":"K3-1-u2-X32"}],"explanation":["텅 빈 방","작게","아쉬움"],"asset":{"type":"passage","lines":["하람이네가 이사 가는 날이에요.","하람이는 텅 빈 방을 가만히 둘러보았어요.","「이제 이 창문도 못 보겠네.」 하람이가 작게 말했어요.","그때 은솔이가 헐레벌떡 뛰어왔어요.","「하람아, 잠깐만!」","은솔이가 내민 것은 반 친구들이 쓴 편지 묶음이었어요.","「우아, 이걸 다 썼어?」 하람이가 눈을 동그랗게 떴어요."],"title":"이사 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
