INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_challenge#3','kor',3,1,'u2','L09','g3_1_kor_u2_L09_challenge','lesson_challenge','K3-1-u2-C26',3,'mc','auto','실감 나게 읽기에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u2-X26','K3-1-u2-X22']::text[],false,'{"seq":3,"concept":"K3-1-u2-C26","difficulty":3,"kind":"mc","stem":"실감 나게 읽기에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"크기가 아니라 장면과 어울리게 읽는 것이에요.","correct":true},{"t":"언제나 가장 크게 읽어야 실감 나요.","mis":"K3-1-u2-X26"},{"t":"조용한 장면도 소리치듯 읽어야 해요.","mis":"K3-1-u2-X26"},{"t":"목소리는 처음 그대로 두어야 해요.","mis":"K3-1-u2-X22"}],"explanation":["크기?","어울림!","장면에 맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_challenge#4','kor',3,1,'u2','L09','g3_1_kor_u2_L09_challenge','lesson_challenge','K3-1-u2-C27',3,'mc','auto','라온이는 부끄러워서 실감 나게 읽기를 하지 않으려 해요. 라온이에게 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X27','K3-1-u2-X26','K3-1-u2-X30']::text[],false,'{"seq":4,"concept":"K3-1-u2-C27","difficulty":3,"kind":"mc","stem":"라온이는 부끄러워서 실감 나게 읽기를 하지 않으려 해요. 라온이에게 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「목소리를 조금 낮추는 것처럼 한 가지만 바꿔 읽어 보자.」","correct":true},{"t":"「연기 잘하는 사람만 하는 거니까 안 해도 돼.」","mis":"K3-1-u2-X27"},{"t":"「아주 크게 소리치기만 하면 돼.」","mis":"K3-1-u2-X26"},{"t":"「그것도 못 하면 어떡해.」","mis":"K3-1-u2-X30"}],"explanation":["작은 바꿈","한 가지만","시작해요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_challenge#5','kor',3,1,'u2','L09','g3_1_kor_u2_L09_challenge','lesson_challenge','K3-1-u2-C25',3,'mc','auto','「이사 가는 날」을 처음부터 끝까지 실감 나게 읽는 방법으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X22','K3-1-u2-X26','K3-1-u2-X25']::text[],false,'{"seq":5,"concept":"K3-1-u2-C25","difficulty":3,"kind":"mc","stem":"「이사 가는 날」을 처음부터 끝까지 실감 나게 읽는 방법으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"처음은 작고 차분하게, 은솔이가 부를 때는 다급하게, 편지를 받을 때는 놀랍고 밝게","correct":true},{"t":"처음부터 끝까지 같은 목소리로","mis":"K3-1-u2-X22"},{"t":"처음부터 끝까지 가장 큰 목소리로","mis":"K3-1-u2-X26"},{"t":"처음은 신나게, 편지를 받을 때는 슬프게","mis":"K3-1-u2-X25"}],"explanation":["장면마다","마음이 달라요","목소리도 바꾸기"],"asset":{"type":"passage","lines":["하람이네가 이사 가는 날이에요.","하람이는 텅 빈 방을 가만히 둘러보았어요.","「이제 이 창문도 못 보겠네.」 하람이가 작게 말했어요.","그때 은솔이가 헐레벌떡 뛰어왔어요.","「하람아, 잠깐만!」","은솔이가 내민 것은 반 친구들이 쓴 편지 묶음이었어요.","「우아, 이걸 다 썼어?」 하람이가 눈을 동그랗게 떴어요."],"title":"이사 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_challenge#6','kor',3,1,'u2','L09','g3_1_kor_u2_L09_challenge','lesson_challenge','K3-1-u2-C21',3,'mc','auto','은솔이가 헐레벌떡 뛰어온 까닭으로 가장 알맞게 짐작한 것은 무엇일까요?',ARRAY['K3-1-u2-X23','K3-1-u2-X32']::text[],false,'{"seq":6,"concept":"K3-1-u2-C21","difficulty":3,"kind":"mc","stem":"은솔이가 헐레벌떡 뛰어온 까닭으로 가장 알맞게 짐작한 것은 무엇일까요?","options":[{"t":"하람이가 떠나기 전에 친구들의 편지를 건네주고 싶어서","correct":true},{"t":"하람이를 놀리고 싶어서","mis":"K3-1-u2-X23"},{"t":"달리기 연습을 하고 싶어서","mis":"K3-1-u2-X32"},{"t":"아무 까닭 없이 그냥","mis":"K3-1-u2-X32"}],"explanation":["뛰어옴","편지 묶음","근거로 짐작"],"asset":{"type":"passage","lines":["하람이네가 이사 가는 날이에요.","하람이는 텅 빈 방을 가만히 둘러보았어요.","「이제 이 창문도 못 보겠네.」 하람이가 작게 말했어요.","그때 은솔이가 헐레벌떡 뛰어왔어요.","「하람아, 잠깐만!」","은솔이가 내민 것은 반 친구들이 쓴 편지 묶음이었어요.","「우아, 이걸 다 썼어?」 하람이가 눈을 동그랗게 떴어요."],"title":"이사 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_challenge#7','kor',3,1,'u2','L09','g3_1_kor_u2_L09_challenge','lesson_challenge','K3-1-u2-C24',3,'mc','auto','「하람아, 잠깐만!」을 실감 나게 읽는 방법으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X25','K3-1-u2-X22']::text[],false,'{"seq":7,"concept":"K3-1-u2-C24","difficulty":3,"kind":"mc","stem":"「하람아, 잠깐만!」을 실감 나게 읽는 방법으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"숨이 찬 듯 다급하고 큰 목소리로, 손을 흔들며 읽는다","correct":true},{"t":"졸린 듯 느리고 작게 읽는다","mis":"K3-1-u2-X25"},{"t":"화난 듯 찡그리며 읽는다","mis":"K3-1-u2-X25"},{"t":"아무 표정 없이 글자만 읽는다","mis":"K3-1-u2-X22"}],"explanation":["헐레벌떡","다급함","큰 목소리가 어울리는 장면"],"asset":{"type":"passage","lines":["하람이네가 이사 가는 날이에요.","하람이는 텅 빈 방을 가만히 둘러보았어요.","「이제 이 창문도 못 보겠네.」 하람이가 작게 말했어요.","그때 은솔이가 헐레벌떡 뛰어왔어요.","「하람아, 잠깐만!」","은솔이가 내민 것은 반 친구들이 쓴 편지 묶음이었어요.","「우아, 이걸 다 썼어?」 하람이가 눈을 동그랗게 떴어요."],"title":"이사 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_challenge#8','kor',3,1,'u2','L09','g3_1_kor_u2_L09_challenge','lesson_challenge','K3-1-u2-C21',4,'essay','teacher','「이사 가는 날」에서 하람이의 마음이 드러난 곳을 두 군데 찾아, 그때의 마음과 그렇게 짐작한 근거를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u2-C21","difficulty":4,"kind":"essay","stem":"「이사 가는 날」에서 하람이의 마음이 드러난 곳을 두 군데 찾아, 그때의 마음과 그렇게 짐작한 근거를 쓰세요.","answer_guide":{"answer":"예: 텅 빈 방을 둘러보며 「이제 이 창문도 못 보겠네.」라고 작게 말한 곳에서 아쉬운 마음을 알 수 있다. 「우아, 이걸 다 썼어?」 하며 눈을 동그랗게 뜬 곳에서 놀랍고 기쁜 마음을 알 수 있다.","scoring_points":["두 군데를 찾았는가","그때의 마음을 썼는가","인물의 말이나 행동을 근거로 들었는가"]},"explanation":["두 군데","마음","근거"],"asset":{"type":"passage","lines":["하람이네가 이사 가는 날이에요.","하람이는 텅 빈 방을 가만히 둘러보았어요.","「이제 이 창문도 못 보겠네.」 하람이가 작게 말했어요.","그때 은솔이가 헐레벌떡 뛰어왔어요.","「하람아, 잠깐만!」","은솔이가 내민 것은 반 친구들이 쓴 편지 묶음이었어요.","「우아, 이걸 다 썼어?」 하람이가 눈을 동그랗게 떴어요."],"title":"이사 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_challenge#9','kor',3,1,'u2','L09','g3_1_kor_u2_L09_challenge','lesson_challenge','K3-1-u2-C24',4,'essay','teacher','「이제 이 창문도 못 보겠네.」를 실감 나게 읽을 방법을 준언어와 비언어로 나누어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u2-C24","difficulty":4,"kind":"essay","stem":"「이제 이 창문도 못 보겠네.」를 실감 나게 읽을 방법을 준언어와 비언어로 나누어 쓰세요.","answer_guide":{"answer":"예: 준언어 — 작고 느린 목소리로, 끝을 흐리듯 읽는다. 비언어 — 창문을 바라보며 고개를 조금 숙이고 쓸쓸한 표정을 짓는다.","scoring_points":["준언어(목소리)를 썼는가","비언어(표정 · 몸짓)를 썼는가","아쉬운 마음과 어울리는가"]},"explanation":["목소리","표정 · 몸짓","아쉬운 마음"],"asset":{"type":"passage","lines":["하람이네가 이사 가는 날이에요.","하람이는 텅 빈 방을 가만히 둘러보았어요.","「이제 이 창문도 못 보겠네.」 하람이가 작게 말했어요.","그때 은솔이가 헐레벌떡 뛰어왔어요.","「하람아, 잠깐만!」","은솔이가 내민 것은 반 친구들이 쓴 편지 묶음이었어요.","「우아, 이걸 다 썼어?」 하람이가 눈을 동그랗게 떴어요."],"title":"이사 가는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L09_challenge#10','kor',3,1,'u2','L09','g3_1_kor_u2_L09_challenge','lesson_challenge','K3-1-u2-C20',4,'essay','teacher','같은 이야기를 똑같은 목소리로 읽을 때와 실감 나게 읽을 때 듣는 사람에게 어떤 차이가 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u2-C20","difficulty":4,"kind":"essay","stem":"같은 이야기를 똑같은 목소리로 읽을 때와 실감 나게 읽을 때 듣는 사람에게 어떤 차이가 있는지 쓰세요.","answer_guide":{"answer":"예: 똑같은 목소리로 읽으면 장면이 바뀌어도 인물의 마음이 잘 느껴지지 않는다. 실감 나게 읽으면 이야기가 생생하게 살아나고 인물의 마음이 듣는 사람에게 잘 전해진다.","scoring_points":["똑같은 목소리로 읽을 때를 썼는가","실감 나게 읽을 때를 썼는가","듣는 사람에게 생기는 차이를 썼는가"]},"explanation":["같은 목소리","실감 나게","차이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#1','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C28',1,'mc','auto','읽기 발표회를 준비할 때 가장 먼저 할 일은 무엇일까요?',ARRAY['K3-1-u2-X28','K3-1-u2-X29','K3-1-u2-X30']::text[],false,'{"seq":1,"concept":"K3-1-u2-C28","difficulty":1,"kind":"mc","stem":"읽기 발표회를 준비할 때 가장 먼저 할 일은 무엇일까요?","options":[{"t":"읽을 글을 고른다","correct":true},{"t":"아무 준비 없이 바로 나간다","mis":"K3-1-u2-X28"},{"t":"누가 가장 잘 읽는지 미리 정한다","mis":"K3-1-u2-X29"},{"t":"친구가 실수할 곳을 미리 찾는다","mis":"K3-1-u2-X30"}],"explanation":["먼저","읽을 글","고르기"],"asset":{"type":"passage","lines":["우리 반 읽기 발표회","— 읽을 글을 하나 골라요.","— 짜임을 생각하며 ∨ 표시를 해요.","— 알맞은 빠르기로 미리 연습해요.","— 친구가 읽을 때는 끝까지 들어요.","— 잘한 점을 먼저 말해 줘요."],"title":"알림장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#2','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C29',1,'mc','auto','읽기 발표회는 어떤 시간일까요?',ARRAY['K3-1-u2-X29','K3-1-u2-X30']::text[],false,'{"seq":2,"concept":"K3-1-u2-C29","difficulty":1,"kind":"mc","stem":"읽기 발표회는 어떤 시간일까요?","options":[{"t":"읽기를 함께 나누는 시간","correct":true},{"t":"누가 이기는지 겨루는 시간","mis":"K3-1-u2-X29"},{"t":"잘 읽는 사람만 나가는 시간","mis":"K3-1-u2-X29"},{"t":"친구의 실수를 찾는 시간","mis":"K3-1-u2-X30"}],"explanation":["겨루기?","나눔","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#3','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C30',1,'mc','auto','친구가 글을 읽을 때 나는 어떻게 할까요?',ARRAY['K3-1-u2-X30']::text[],false,'{"seq":3,"concept":"K3-1-u2-C30","difficulty":1,"kind":"mc","stem":"친구가 글을 읽을 때 나는 어떻게 할까요?","options":[{"t":"끝까지 귀 기울여 듣는다","correct":true},{"t":"중간에 끼어들어 고쳐 준다","mis":"K3-1-u2-X30"},{"t":"다른 친구와 떠든다","mis":"K3-1-u2-X30"},{"t":"못 읽은 곳을 큰 소리로 말한다","mis":"K3-1-u2-X30"}],"explanation":["친구가","읽을 때","끝까지 듣기"],"asset":{"type":"passage","lines":["우리 반 읽기 발표회","— 읽을 글을 하나 골라요.","— 짜임을 생각하며 ∨ 표시를 해요.","— 알맞은 빠르기로 미리 연습해요.","— 친구가 읽을 때는 끝까지 들어요.","— 잘한 점을 먼저 말해 줘요."],"title":"알림장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#4','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C32',1,'mc','auto','「고양이가」 뒤에 이어 쓰면 뜻이 통하는 말은 무엇일까요?',ARRAY['K3-1-u2-X05']::text[],false,'{"seq":4,"concept":"K3-1-u2-C32","difficulty":1,"kind":"mc","stem":"「고양이가」 뒤에 이어 쓰면 뜻이 통하는 말은 무엇일까요?","options":[{"t":"잠을 잡니다","correct":true},{"t":"맑습니다","mis":"K3-1-u2-X05"},{"t":"선생님입니다","mis":"K3-1-u2-X05"},{"t":"출렁입니다","mis":"K3-1-u2-X05"}],"explanation":["고양이가","무엇을 하나요?","뜻이 통하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#5','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C30',2,'mc','auto','친구의 읽기가 끝난 뒤 말해 주는 차례로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X30']::text[],false,'{"seq":5,"concept":"K3-1-u2-C30","difficulty":2,"kind":"mc","stem":"친구의 읽기가 끝난 뒤 말해 주는 차례로 알맞은 것은 무엇일까요?","options":[{"t":"잘한 점을 먼저, 고칠 점은 하나만 부드럽게","correct":true},{"t":"고칠 점을 먼저 모두 말한다","mis":"K3-1-u2-X30"},{"t":"잘한 점은 말하지 않는다","mis":"K3-1-u2-X30"},{"t":"고칠 점을 친구들 앞에서 크게 외친다","mis":"K3-1-u2-X30"}],"explanation":["잘한 점 먼저","고칠 점 하나","부드럽게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#6','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C28',2,'mc','auto','발표회에서 읽을 글에 ∨ 표시를 하는 까닭은 무엇일까요?',ARRAY['K3-1-u2-X12','K3-1-u2-X16','K3-1-u2-X28']::text[],false,'{"seq":6,"concept":"K3-1-u2-C28","difficulty":2,"kind":"mc","stem":"발표회에서 읽을 글에 ∨ 표시를 하는 까닭은 무엇일까요?","options":[{"t":"짜임에 맞게 쉬어 읽어 뜻을 또렷하게 전하려고","correct":true},{"t":"표시가 많을수록 멋져 보여서","mis":"K3-1-u2-X12"},{"t":"빨리 읽어 끝내려고","mis":"K3-1-u2-X16"},{"t":"준비는 아무렇게나 해도 되니까","mis":"K3-1-u2-X28"}],"explanation":["짜임에 맞게","쉬어 읽기","뜻이 또렷"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#7','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C30',2,'mc','auto','나래 · 서진 · 도윤이의 말 가운데 친구를 배려하며 도와준 말을 모두 고른 것은 무엇일까요?',ARRAY['K3-1-u2-X30']::text[],false,'{"seq":7,"concept":"K3-1-u2-C30","difficulty":2,"kind":"mc","stem":"나래 · 서진 · 도윤이의 말 가운데 친구를 배려하며 도와준 말을 모두 고른 것은 무엇일까요?","options":[{"t":"나래와 서진이의 말","correct":true},{"t":"도윤이의 말만","mis":"K3-1-u2-X30"},{"t":"세 친구의 말 모두","mis":"K3-1-u2-X30"},{"t":"아무의 말도 아님","mis":"K3-1-u2-X30"}],"explanation":["잘한 점","고칠 점 하나","놀리지 않기"],"asset":{"type":"speech","turns":[{"who":"나래","text":"라온아, 연이 날아가는 줄에서 목소리가 밝아서 정말 신났어."},{"who":"서진","text":"마지막 줄은 조금만 천천히 읽으면 더 잘 들릴 것 같아."},{"who":"도윤","text":"너 중간에 한 번 멈췄잖아. 하하, 그것도 못 읽어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#8','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C31',2,'mc','auto','단원이 끝난 뒤에는 어떻게 할까요?',ARRAY['K3-1-u2-X31']::text[],false,'{"seq":8,"concept":"K3-1-u2-C31","difficulty":2,"kind":"mc","stem":"단원이 끝난 뒤에는 어떻게 할까요?","options":[{"t":"책을 읽거나 발표할 때도 계속 또박또박 유창하게 읽는다","correct":true},{"t":"단원이 끝났으니 다시 웅얼거려도 된다","mis":"K3-1-u2-X31"},{"t":"발표회 날에만 또박또박 읽는다","mis":"K3-1-u2-X31"},{"t":"배운 읽기는 국어 책을 읽을 때만 쓴다","mis":"K3-1-u2-X31"}],"explanation":["단원이 끝나도","날마다","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#9','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C32',2,'match','auto','「누가/무엇이」와 뒷부분을 뜻이 통하게 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u2-C32","difficulty":2,"kind":"match","stem":"「누가/무엇이」와 뒷부분을 뜻이 통하게 알맞게 이으세요.","pairs":[{"l":"바다가","r":"넓습니다"},{"l":"형이","r":"공을 찹니다"},{"l":"이분은","r":"우리 선생님입니다"}],"mis":"K3-1-u2-X05","explanation":["바다 — 넓다","형 — 공 차기","이분 — 선생님"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_basic#10','kor',3,1,'u2','L12','g3_1_kor_u2_L12_basic','lesson_basic','K3-1-u2-C29',3,'mc','auto','은솔이는 「나는 잘 못 읽어서 안 나갈래.」라며 차례를 미뤄요. 은솔이에게 해 줄 말로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X29','K3-1-u2-X30','K3-1-u2-X28']::text[],false,'{"seq":10,"concept":"K3-1-u2-C29","difficulty":3,"kind":"mc","stem":"은솔이는 「나는 잘 못 읽어서 안 나갈래.」라며 차례를 미뤄요. 은솔이에게 해 줄 말로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「한 줄만 읽어도 좋아. 우리가 끝까지 들어 줄게.」","correct":true},{"t":"「잘 읽는 사람만 나가면 돼.」","mis":"K3-1-u2-X29"},{"t":"「못 읽으면 웃을 거야.」","mis":"K3-1-u2-X30"},{"t":"「연습 없이 그냥 아무렇게나 읽어.」","mis":"K3-1-u2-X28"}],"explanation":["겨루기 아님","한 줄이라도","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#1','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C28',2,'mc','auto','읽기 발표회 준비 차례로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X28']::text[],false,'{"seq":1,"concept":"K3-1-u2-C28","difficulty":2,"kind":"mc","stem":"읽기 발표회 준비 차례로 알맞은 것은 무엇일까요?","options":[{"t":"글 고르기 → ∨ 표시하기 → 알맞은 빠르기로 연습하기","correct":true},{"t":"연습하기 → 글 고르기 → ∨ 표시하기","mis":"K3-1-u2-X28"},{"t":"∨ 표시하기 → 발표하기 → 글 고르기","mis":"K3-1-u2-X28"},{"t":"준비 없이 바로 발표하기","mis":"K3-1-u2-X28"}],"explanation":["고르고","표시하고","연습"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#2','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C32',2,'mc','auto','「누가/무엇이」와 뒷부분의 뜻이 통하는 문장은 무엇일까요?',ARRAY['K3-1-u2-X05']::text[],false,'{"seq":2,"concept":"K3-1-u2-C32","difficulty":2,"kind":"mc","stem":"「누가/무엇이」와 뒷부분의 뜻이 통하는 문장은 무엇일까요?","options":[{"t":"꽃이 활짝 핍니다.","correct":true},{"t":"꽃이 멍멍 짖습니다.","mis":"K3-1-u2-X05"},{"t":"하늘이 깡충깡충 뜁니다.","mis":"K3-1-u2-X05"},{"t":"시계가 맛있습니다.","mis":"K3-1-u2-X05"}],"explanation":["꽃이","핍니다","뜻이 통해요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#3','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C30',3,'mc','auto','도윤이의 말을 친구를 배려하는 말로 알맞게 바꾼 것은 무엇일까요?',ARRAY['K3-1-u2-X30','K3-1-u2-X29']::text[],false,'{"seq":3,"concept":"K3-1-u2-C30","difficulty":3,"kind":"mc","stem":"도윤이의 말을 친구를 배려하는 말로 알맞게 바꾼 것은 무엇일까요?","options":[{"t":"「중간에 잠깐 멈췄지만 끝까지 또박또박 읽은 점이 멋졌어.」","correct":true},{"t":"「멈춘 곳을 하나도 빠짐없이 다 적어 줄게.」","mis":"K3-1-u2-X30"},{"t":"「너는 다음부터 나오지 마.」","mis":"K3-1-u2-X29"},{"t":"「그냥 하하 웃고 넘어가자.」","mis":"K3-1-u2-X30"}],"explanation":["잘한 점 먼저","놀리지 않기","배려"],"asset":{"type":"speech","turns":[{"who":"나래","text":"라온아, 연이 날아가는 줄에서 목소리가 밝아서 정말 신났어."},{"who":"서진","text":"마지막 줄은 조금만 천천히 읽으면 더 잘 들릴 것 같아."},{"who":"도윤","text":"너 중간에 한 번 멈췄잖아. 하하, 그것도 못 읽어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#4','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C29',3,'mc','auto','읽기 발표회에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u2-X29','K3-1-u2-X28']::text[],false,'{"seq":4,"concept":"K3-1-u2-C29","difficulty":3,"kind":"mc","stem":"읽기 발표회에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"저마다 고른 글을 읽어 즐거움을 나누는 자리예요.","correct":true},{"t":"점수를 매겨 1등을 뽑는 자리예요.","mis":"K3-1-u2-X29"},{"t":"잘 읽는 사람만 나가는 자리예요.","mis":"K3-1-u2-X29"},{"t":"준비하지 않아도 되는 자리예요.","mis":"K3-1-u2-X28"}],"explanation":["겨루기?","나눔","즐거움"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#5','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C31',3,'mc','auto','이 단원에서 배운 것을 생활에서 잘 실천한 친구는 누구일까요?',ARRAY['K3-1-u2-X31','K3-1-u2-X16','K3-1-u2-X02']::text[],false,'{"seq":5,"concept":"K3-1-u2-C31","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 것을 생활에서 잘 실천한 친구는 누구일까요?","options":[{"t":"동생에게 그림책을 읽어 줄 때 인물의 마음에 맞게 목소리를 바꾼 친구","correct":true},{"t":"단원이 끝나 이제 소리 내어 읽지 않는 친구","mis":"K3-1-u2-X31"},{"t":"발표할 때 숨도 쉬지 않고 빨리 읽은 친구","mis":"K3-1-u2-X16"},{"t":"알림장을 웅얼웅얼 읽어 준 친구","mis":"K3-1-u2-X02"}],"explanation":["생활 속","실감 나게","이어 가기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#6','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C28',3,'mc','auto','발표회에서 이야기를 실감 나게 읽으려고 할 때 미리 준비할 것으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X26','K3-1-u2-X22','K3-1-u2-X28']::text[],false,'{"seq":6,"concept":"K3-1-u2-C28","difficulty":3,"kind":"mc","stem":"발표회에서 이야기를 실감 나게 읽으려고 할 때 미리 준비할 것으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"인물의 마음을 정하고 어울리는 목소리 · 표정 · 몸짓을 떠올린다","correct":true},{"t":"모든 줄을 가장 큰 목소리 하나로 정한다","mis":"K3-1-u2-X26"},{"t":"인물의 마음은 생각하지 않고 같은 목소리로 정한다","mis":"K3-1-u2-X22"},{"t":"준비 없이 그날 기분대로 읽는다","mis":"K3-1-u2-X28"}],"explanation":["인물의 마음","목소리 · 표정","미리 준비"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#7','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C32',3,'blank','auto','「우리 반 화분이 (    ).」의 빈칸에 들어가 뜻이 통하는 말은 무엇일까요?',ARRAY['K3-1-u2-X05']::text[],false,'{"seq":7,"concept":"K3-1-u2-C32","difficulty":3,"kind":"blank","stem":"「우리 반 화분이 (    ).」의 빈칸에 들어가 뜻이 통하는 말은 무엇일까요?","options":[{"t":"쑥쑥 자랍니다","correct":true},{"t":"멍멍 짖습니다","mis":"K3-1-u2-X05"},{"t":"3학년 학생입니다","mis":"K3-1-u2-X05"},{"t":"운동장을 뛰어다닙니다","mis":"K3-1-u2-X05"}],"explanation":["화분이","어찌하나요?","뜻이 통하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#8','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C28',4,'essay','teacher','읽기 발표회에서 읽을 글을 하나 정했다고 생각하고, 준비할 일을 차례대로 세 가지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-1-u2-C28","difficulty":4,"kind":"essay","stem":"읽기 발표회에서 읽을 글을 하나 정했다고 생각하고, 준비할 일을 차례대로 세 가지 쓰세요.","answer_guide":{"answer":"예: 첫째, 읽을 글을 고른다. 둘째, 짜임을 생각하며 「누가/무엇이」 다음에 ∨, 문장 끝에 ∨∨를 표시한다. 셋째, 알맞은 빠르기로 또박또박 소리 내어 여러 번 연습한다.","scoring_points":["글 고르기를 썼는가","∨ 표시를 썼는가","알맞은 빠르기로 연습하기를 썼는가"]},"explanation":["고르기","표시하기","연습하기"],"asset":{"type":"passage","lines":["우리 반 읽기 발표회","— 읽을 글을 하나 골라요.","— 짜임을 생각하며 ∨ 표시를 해요.","— 알맞은 빠르기로 미리 연습해요.","— 친구가 읽을 때는 끝까지 들어요.","— 잘한 점을 먼저 말해 줘요."],"title":"알림장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#9','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C30',4,'essay','teacher','나래 · 서진 · 도윤이의 말 가운데 고쳐야 할 말을 찾아 까닭을 쓰고, 친구를 배려하는 말로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-1-u2-C30","difficulty":4,"kind":"essay","stem":"나래 · 서진 · 도윤이의 말 가운데 고쳐야 할 말을 찾아 까닭을 쓰고, 친구를 배려하는 말로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 도윤이의 말을 고쳐야 한다. 친구가 멈춘 곳을 놀려서 친구가 다시 읽고 싶은 마음이 사라지기 때문이다. 「끝까지 또박또박 읽어서 잘 들렸어. 다음엔 숨을 고르고 천천히 읽으면 더 좋겠어.」","scoring_points":["고칠 말을 찾았는가","까닭을 썼는가","잘한 점을 먼저 말하는 배려하는 말로 바꾸었는가"]},"explanation":["찾기","까닭","바꾸기"],"asset":{"type":"speech","turns":[{"who":"나래","text":"라온아, 연이 날아가는 줄에서 목소리가 밝아서 정말 신났어."},{"who":"서진","text":"마지막 줄은 조금만 천천히 읽으면 더 잘 들릴 것 같아."},{"who":"도윤","text":"너 중간에 한 번 멈췄잖아. 하하, 그것도 못 읽어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_L12_challenge#10','kor',3,1,'u2','L12','g3_1_kor_u2_L12_challenge','lesson_challenge','K3-1-u2-C31',4,'essay','teacher','「분명하고 유창하게」에서 배운 것을 앞으로 생활에서 어떻게 실천할지 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-1-u2-C31","difficulty":4,"kind":"essay","stem":"「분명하고 유창하게」에서 배운 것을 앞으로 생활에서 어떻게 실천할지 두 가지 쓰세요.","answer_guide":{"answer":"예: 수업 시간에 발표할 때 「누가/무엇이」 다음에서 쉬며 또박또박 읽겠다. 동생에게 책을 읽어 줄 때 인물의 마음에 맞게 목소리를 바꾸어 실감 나게 읽어 주겠다.","scoring_points":["실천할 일 두 가지를 썼는가","단원에서 배운 것과 이어지는가","생활 속 상황이 드러나는가"]},"explanation":["발표","책 읽어 주기","날마다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#1','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C4',1,'mc','auto','단원 정리: 문장은 「누가/무엇이」와 무엇으로 이루어질까요?',ARRAY['K3-1-u2-X04','K3-1-u2-X09']::text[],false,'{"seq":1,"concept":"K3-1-u2-C4","difficulty":1,"kind":"mc","stem":"단원 정리: 문장은 「누가/무엇이」와 무엇으로 이루어질까요?","options":[{"t":"「어찌하다 · 어떠하다 · 무엇이다」","correct":true},{"t":"글의 제목","mis":"K3-1-u2-X04"},{"t":"글자 수","mis":"K3-1-u2-X09"},{"t":"그림","mis":"K3-1-u2-X04"}],"explanation":["앞부분","뒷부분","두 부분"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
