INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#11','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C13',2,'mc','auto','「가을 운동회가 ∨ 열렸습니다. ∨∨」를 읽는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X13','K3-1-u2-X14']::text[],false,'{"seq":11,"concept":"K3-1-u2-C13","difficulty":2,"kind":"mc","stem":"「가을 운동회가 ∨ 열렸습니다. ∨∨」를 읽는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"∨에서 조금 쉬고, ∨∨에서 조금 더 쉬어요.","correct":true},{"t":"∨에서 더 오래, ∨∨에서 짧게 쉬어요.","mis":"K3-1-u2-X13"},{"t":"표시와 상관없이 붙여 읽어요.","mis":"K3-1-u2-X14"},{"t":"표시가 있는 곳의 낱말을 빼요.","mis":"K3-1-u2-X14"}],"explanation":["∨ 조금","∨∨ 조금 더","쉬어 읽기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#12','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C16',2,'mc','auto','라온이가 「가을 운동회」를 숨도 쉬지 않고 아주 빠르게 읽었어요. 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X16','K3-1-u2-X17','K3-1-u2-X20']::text[],false,'{"seq":12,"concept":"K3-1-u2-C16","difficulty":2,"kind":"mc","stem":"라온이가 「가을 운동회」를 숨도 쉬지 않고 아주 빠르게 읽었어요. 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「듣는 사람이 알아듣게 알맞은 빠르기로 읽자.」","correct":true},{"t":"「더 빨리 읽으면 최고야.」","mis":"K3-1-u2-X16"},{"t":"「한 글자씩 아주 느리게 읽어.」","mis":"K3-1-u2-X17"},{"t":"「어려운 낱말은 건너뛰자.」","mis":"K3-1-u2-X20"}],"explanation":["너무 빠르면","알아듣기 어려워요","알맞게"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
