INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#14','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C26',2,'mc','auto','「아쉽다….」처럼 조용한 장면은 어떻게 읽으면 실감 날까요?',ARRAY['K3-1-u2-X26','K3-1-u2-X25','K3-1-u2-X22']::text[],false,'{"seq":14,"concept":"K3-1-u2-C26","difficulty":2,"kind":"mc","stem":"「아쉽다….」처럼 조용한 장면은 어떻게 읽으면 실감 날까요?","options":[{"t":"작고 느린 목소리로 읽어요.","correct":true},{"t":"가장 크게 소리쳐 읽어요.","mis":"K3-1-u2-X26"},{"t":"밝고 신나게 읽어요.","mis":"K3-1-u2-X25"},{"t":"앞 줄과 똑같은 목소리로 읽어요.","mis":"K3-1-u2-X22"}],"explanation":["조용한 장면","작게","어울림"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#15','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C30',2,'mc','auto','친구의 읽기를 듣고 해 줄 칭찬으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X30','K3-1-u2-X29']::text[],false,'{"seq":15,"concept":"K3-1-u2-C30","difficulty":2,"kind":"mc","stem":"친구의 읽기를 듣고 해 줄 칭찬으로 알맞은 것은 무엇일까요?","options":[{"t":"「또박또박 읽어서 모든 낱말이 잘 들렸어.」","correct":true},{"t":"「중간에 멈춘 곳을 다 말해 줄게.」","mis":"K3-1-u2-X30"},{"t":"「나보다 못 읽었어.」","mis":"K3-1-u2-X29"},{"t":"「듣느라 지루했어.」","mis":"K3-1-u2-X30"}],"explanation":["구체적으로","잘한 점","칭찬"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#16','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C3',2,'mc','auto','은솔이가 유치원 동생들에게 그림책을 읽어 줘요. 가장 알맞은 읽기는 무엇일까요?',ARRAY['K3-1-u2-X03','K3-1-u2-X02','K3-1-u2-X01']::text[],false,'{"seq":16,"concept":"K3-1-u2-C3","difficulty":2,"kind":"mc","stem":"은솔이가 유치원 동생들에게 그림책을 읽어 줘요. 가장 알맞은 읽기는 무엇일까요?","options":[{"t":"다정하게, 조금 천천히 또박또박 읽는다","correct":true},{"t":"방송하듯 힘차게만 읽는다","mis":"K3-1-u2-X03"},{"t":"빠르게 웅얼거리며 읽는다","mis":"K3-1-u2-X02"},{"t":"목소리만 크게 하고 낱말은 뭉개어 읽는다","mis":"K3-1-u2-X01"}],"explanation":["듣는 사람","동생들","다정하고 천천히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#17','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C8',3,'mc','auto','「우리 반 친구들이 운동장에서 신나게 뛰어놉니다.」를 두 부분으로 바르게 나눈 것은 무엇일까요?',ARRAY['K3-1-u2-X09']::text[],false,'{"seq":17,"concept":"K3-1-u2-C8","difficulty":3,"kind":"mc","stem":"「우리 반 친구들이 운동장에서 신나게 뛰어놉니다.」를 두 부분으로 바르게 나눈 것은 무엇일까요?","options":[{"t":"우리 반 친구들이 / 운동장에서 신나게 뛰어놉니다.","correct":true},{"t":"우리 반 / 친구들이 운동장에서 신나게 뛰어놉니다.","mis":"K3-1-u2-X09"},{"t":"우리 반 친구들이 운동장에서 / 신나게 뛰어놉니다.","mis":"K3-1-u2-X09"},{"t":"우리 반 친구들이 운동장에서 신나게 / 뛰어놉니다.","mis":"K3-1-u2-X09"}],"explanation":["누가?","우리 반 친구들이","나머지는 한 덩어리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#18','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C12',3,'mc','auto','두 친구가 「청군과 백군이 줄을 당깁니다.」를 읽었어요. 바르게 읽은 친구의 읽기는 무엇일까요?',ARRAY['K3-1-u2-X11','K3-1-u2-X13','K3-1-u2-X12']::text[],false,'{"seq":18,"concept":"K3-1-u2-C12","difficulty":3,"kind":"mc","stem":"두 친구가 「청군과 백군이 줄을 당깁니다.」를 읽었어요. 바르게 읽은 친구의 읽기는 무엇일까요?","options":[{"t":"청군과 백군이 ∨ 줄을 당깁니다. ∨∨","correct":true},{"t":"청군과 ∨ 백 ∨ 군이 줄을 당깁니다. ∨∨","mis":"K3-1-u2-X11"},{"t":"청군과 백군이 ∨∨ 줄을 당깁니다. ∨","mis":"K3-1-u2-X13"},{"t":"청 ∨ 군과 ∨ 백 ∨ 군이 ∨ 줄을 ∨ 당깁니다.","mis":"K3-1-u2-X12"}],"explanation":["누가?","다음에 ∨","끝에 ∨∨"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#19','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C16',3,'mc','auto','나래는 「가을 운동회」를 한 글자씩 끊어 아주 느리게 읽었어요. 가장 알맞은 도움말은 무엇일까요?',ARRAY['K3-1-u2-X17','K3-1-u2-X16','K3-1-u2-X20']::text[],false,'{"seq":19,"concept":"K3-1-u2-C16","difficulty":3,"kind":"mc","stem":"나래는 「가을 운동회」를 한 글자씩 끊어 아주 느리게 읽었어요. 가장 알맞은 도움말은 무엇일까요?","options":[{"t":"「낱말을 이어서 알맞은 빠르기로 읽으면 뜻이 더 잘 들려.」","correct":true},{"t":"「더 느리게 읽을수록 분명해.」","mis":"K3-1-u2-X17"},{"t":"「아주 빠르게 읽으면 다 괜찮아.」","mis":"K3-1-u2-X16"},{"t":"「모르는 낱말은 건너뛰자.」","mis":"K3-1-u2-X20"}],"explanation":["너무 느리면","뚝뚝 끊겨요","알맞게"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#20','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C25',3,'mc','auto','「가을 운동회」를 실감 나게 읽는 흐름으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X22','K3-1-u2-X26','K3-1-u2-X25']::text[],false,'{"seq":20,"concept":"K3-1-u2-C25","difficulty":3,"kind":"mc","stem":"「가을 운동회」를 실감 나게 읽는 흐름으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"줄을 당길 때는 힘차게, 이겼을 때는 밝고 높게, 청군 친구는 작고 느리게","correct":true},{"t":"처음부터 끝까지 같은 목소리로","mis":"K3-1-u2-X22"},{"t":"처음부터 끝까지 가장 큰 목소리로","mis":"K3-1-u2-X26"},{"t":"이겼을 때는 슬프게, 청군 친구는 신나게","mis":"K3-1-u2-X25"}],"explanation":["장면마다","마음이 달라요","바꾸어 읽기"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#21','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C30',3,'mc','auto','서진이가 친구에게 해 준 「마지막 줄은 조금만 천천히 읽으면 더 잘 들릴 것 같아.」는 어떤 말일까요?',ARRAY['K3-1-u2-X30','K3-1-u2-X29','K3-1-u2-X28']::text[],false,'{"seq":21,"concept":"K3-1-u2-C30","difficulty":3,"kind":"mc","stem":"서진이가 친구에게 해 준 「마지막 줄은 조금만 천천히 읽으면 더 잘 들릴 것 같아.」는 어떤 말일까요?","options":[{"t":"고칠 점을 하나만 부드럽게 말해 준 말","correct":true},{"t":"친구를 놀리는 말","mis":"K3-1-u2-X30"},{"t":"겨루어 이기려는 말","mis":"K3-1-u2-X29"},{"t":"준비를 하지 말라는 말","mis":"K3-1-u2-X28"}],"explanation":["고칠 점","하나만","부드럽게"],"asset":{"type":"speech","turns":[{"who":"나래","text":"라온아, 연이 날아가는 줄에서 목소리가 밝아서 정말 신났어."},{"who":"서진","text":"마지막 줄은 조금만 천천히 읽으면 더 잘 들릴 것 같아."},{"who":"도윤","text":"너 중간에 한 번 멈췄잖아. 하하, 그것도 못 읽어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#22','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C1',3,'mc','auto','「분명하고 유창하게」를 가장 잘 정리한 친구의 말은 무엇일까요?',ARRAY['K3-1-u2-X01','K3-1-u2-X03','K3-1-u2-X02']::text[],false,'{"seq":22,"concept":"K3-1-u2-C1","difficulty":3,"kind":"mc","stem":"「분명하고 유창하게」를 가장 잘 정리한 친구의 말은 무엇일까요?","options":[{"t":"「짜임을 알고 띄어 읽고, 알맞은 빠르기로, 인물의 마음을 살려 읽으면 뜻이 잘 전해져.」","correct":true},{"t":"「크게만, 빠르게만 읽으면 돼.」","mis":"K3-1-u2-X01"},{"t":"「누구에게나 똑같이 읽으면 돼.」","mis":"K3-1-u2-X03"},{"t":"「눈으로만 읽어도 똑같아.」","mis":"K3-1-u2-X02"}],"explanation":["짜임","유창","실감"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#23','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C5',4,'essay','teacher','「가을 운동회」에서 뒷부분이 어찌하다 · 어떠하다 · 무엇이다인 문장을 하나씩 찾아 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u2-C5","difficulty":4,"kind":"essay","stem":"「가을 운동회」에서 뒷부분이 어찌하다 · 어떠하다 · 무엇이다인 문장을 하나씩 찾아 쓰세요.","answer_guide":{"answer":"예: 어찌하다 — 청군과 백군이 줄을 당깁니다. 어떠하다 — 하늘이 맑습니다. 무엇이다 — 도윤이는 백군입니다.","scoring_points":["어찌하다 문장을 찾았는가","어떠하다 문장을 찾았는가","무엇이다 문장을 찾았는가"]},"explanation":["움직임","상태","무엇인지"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#24','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C17',4,'essay','teacher','「가을 운동회」의 다섯째 줄을 읽을 때 쉼표와 마침표에서 각각 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u2-C17","difficulty":4,"kind":"essay","stem":"「가을 운동회」의 다섯째 줄을 읽을 때 쉼표와 마침표에서 각각 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 「영차,」의 쉼표에서는 조금 쉬고, 「외쳤습니다.」의 마침표 뒤에서는 조금 더 쉰다.","scoring_points":["쉼표에서 조금 쉰다고 썼는가","마침표에서 조금 더 쉰다고 썼는가","줄 안의 부호를 바르게 찾았는가"]},"explanation":["쉼표","마침표","쉬는 정도"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_a#25','kor',3,1,'u2','','g3_1_kor_u2_review_a','unit_review','K3-1-u2-C28',4,'essay','teacher','읽기 발표회에서 「가을 운동회」를 읽는다고 생각하고, 준비할 일을 차례대로 세 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u2-C28","difficulty":4,"kind":"essay","stem":"읽기 발표회에서 「가을 운동회」를 읽는다고 생각하고, 준비할 일을 차례대로 세 가지 쓰세요.","answer_guide":{"answer":"예: 첫째, 문장마다 「누가/무엇이」 다음에 ∨, 끝에 ∨∨를 표시한다. 둘째, 「영차, 영차!」와 「이겼다!」를 어떤 목소리와 몸짓으로 읽을지 정한다. 셋째, 알맞은 빠르기로 여러 번 소리 내어 연습한다.","scoring_points":["∨ 표시를 썼는가","목소리 · 몸짓 정하기를 썼는가","알맞은 빠르기로 연습하기를 썼는가"]},"explanation":["표시","마음 살리기","연습"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#1','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C5',1,'mc','auto','「가을 운동회」의 「청군과 백군이 줄을 당깁니다.」의 뒷부분은 무엇을 나타낼까요?',ARRAY['K3-1-u2-X06','K3-1-u2-X08','K3-1-u2-X09']::text[],false,'{"seq":1,"concept":"K3-1-u2-C5","difficulty":1,"kind":"mc","stem":"「가을 운동회」의 「청군과 백군이 줄을 당깁니다.」의 뒷부분은 무엇을 나타낼까요?","options":[{"t":"움직임 — 어찌하다","correct":true},{"t":"상태 — 어떠하다","mis":"K3-1-u2-X06"},{"t":"무엇인지 — 무엇이다","mis":"K3-1-u2-X08"},{"t":"누가 — 문장의 앞부분","mis":"K3-1-u2-X09"}],"explanation":["당기기","움직임","어찌하다"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
