INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#8','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C3',1,'mc','auto','학교 방송으로 알릴 때 알맞은 읽기는 무엇일까요?',ARRAY['K3-1-u2-X02','K3-1-u2-X03','K3-1-u2-X01']::text[],false,'{"seq":8,"concept":"K3-1-u2-C3","difficulty":1,"kind":"mc","stem":"학교 방송으로 알릴 때 알맞은 읽기는 무엇일까요?","options":[{"t":"또박또박, 알맞은 빠르기로 읽기","correct":true},{"t":"웅얼웅얼 빠르게 읽기","mis":"K3-1-u2-X02"},{"t":"동생에게 읽어 주듯 속삭이며 읽기","mis":"K3-1-u2-X03"},{"t":"크게만 소리치고 낱말은 뭉개어 읽기","mis":"K3-1-u2-X01"}],"explanation":["방송","한 번만 들어요","또박또박"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#9','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C7',2,'mc','auto','「가을 운동회」에서 뒷부분이 「무엇이다」인 문장은 무엇일까요?',ARRAY['K3-1-u2-X07','K3-1-u2-X08']::text[],false,'{"seq":9,"concept":"K3-1-u2-C7","difficulty":2,"kind":"mc","stem":"「가을 운동회」에서 뒷부분이 「무엇이다」인 문장은 무엇일까요?","options":[{"t":"도윤이는 백군입니다.","correct":true},{"t":"하늘이 맑습니다.","mis":"K3-1-u2-X07"},{"t":"아이들이 힘껏 외쳤습니다.","mis":"K3-1-u2-X08"},{"t":"줄이 백군 쪽으로 조금씩 끌려왔습니다.","mis":"K3-1-u2-X08"}],"explanation":["백군입니다","무엇인지","무엇이다"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
