INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#14','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C27',2,'mc','auto','실감 나게 읽기가 어렵다는 친구에게 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X27','K3-1-u2-X26','K3-1-u2-X30']::text[],false,'{"seq":14,"concept":"K3-1-u2-C27","difficulty":2,"kind":"mc","stem":"실감 나게 읽기가 어렵다는 친구에게 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「빠르기만 조금 바꾸어도 마음이 전해져. 한 가지부터 해 보자.」","correct":true},{"t":"「연기 잘하는 사람만 하는 거야.」","mis":"K3-1-u2-X27"},{"t":"「크게만 소리치면 돼.」","mis":"K3-1-u2-X26"},{"t":"「못 하면 놀림받을 거야.」","mis":"K3-1-u2-X30"}],"explanation":["작은 바꿈","한 가지","누구나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
