INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#16','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C1',2,'mc','auto','「분명하고 유창하게」라는 단원 이름의 뜻으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X01','K3-1-u2-X02','K3-1-u2-X03']::text[],false,'{"seq":16,"concept":"K3-1-u2-C1","difficulty":2,"kind":"mc","stem":"「분명하고 유창하게」라는 단원 이름의 뜻으로 알맞은 것은 무엇일까요?","options":[{"t":"또렷하게, 알맞은 빠르기로 자연스럽게 읽고 말하기","correct":true},{"t":"크게만, 빠르게만 읽기","mis":"K3-1-u2-X01"},{"t":"눈으로만 조용히 읽기","mis":"K3-1-u2-X02"},{"t":"누구에게나 같은 목소리로 읽기","mis":"K3-1-u2-X03"}],"explanation":["분명하게","유창하게","단원 이름"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#17','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C7',3,'mc','auto','「이것은 내 필통입니다.」와 짜임이 같은 문장은 무엇일까요?',ARRAY['K3-1-u2-X07','K3-1-u2-X08']::text[],false,'{"seq":17,"concept":"K3-1-u2-C7","difficulty":3,"kind":"mc","stem":"「이것은 내 필통입니다.」와 짜임이 같은 문장은 무엇일까요?","options":[{"t":"저분은 우리 이모입니다.","correct":true},{"t":"필통이 예쁩니다.","mis":"K3-1-u2-X07"},{"t":"동생이 필통을 엽니다.","mis":"K3-1-u2-X08"},{"t":"연필이 깁니다.","mis":"K3-1-u2-X07"}],"explanation":["필통입니다","무엇이다","같은 짜임"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#18','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C13',3,'mc','auto','「가을 운동회」의 첫 두 줄에 표시를 바르게 한 것은 무엇일까요?',ARRAY['K3-1-u2-X13','K3-1-u2-X11','K3-1-u2-X14']::text[],false,'{"seq":18,"concept":"K3-1-u2-C13","difficulty":3,"kind":"mc","stem":"「가을 운동회」의 첫 두 줄에 표시를 바르게 한 것은 무엇일까요?","options":[{"t":"가을 운동회가 ∨ 열렸습니다. ∨∨ 하늘이 ∨ 맑습니다. ∨∨","correct":true},{"t":"가을 운동회가 ∨∨ 열렸습니다. ∨ 하늘이 ∨∨ 맑습니다. ∨","mis":"K3-1-u2-X13"},{"t":"가을 ∨ 운동 ∨ 회가 열렸습니다. 하늘이 맑습니다.","mis":"K3-1-u2-X11"},{"t":"가을 운동회가 열렸습니다 하늘이 맑습니다","mis":"K3-1-u2-X14"}],"explanation":["∨","∨∨","바른 자리"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#19','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C17',3,'mc','auto','「누가 이겼을까요? 백군이 이겼습니다.」를 바르게 읽는 방법은 무엇일까요?',ARRAY['K3-1-u2-X19','K3-1-u2-X18','K3-1-u2-X20']::text[],false,'{"seq":19,"concept":"K3-1-u2-C17","difficulty":3,"kind":"mc","stem":"「누가 이겼을까요? 백군이 이겼습니다.」를 바르게 읽는 방법은 무엇일까요?","options":[{"t":"앞 문장은 끝을 올리고, 마침표 뒤에서 조금 더 쉬어요.","correct":true},{"t":"두 문장 모두 끝을 내리고 쉬지 않아요.","mis":"K3-1-u2-X19"},{"t":"두 문장을 쉬지 않고 붙여 읽어요.","mis":"K3-1-u2-X18"},{"t":"앞 문장을 빼고 뒷문장만 읽어요.","mis":"K3-1-u2-X20"}],"explanation":["물음표","마침표","부호에 맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#20','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C26',3,'mc','auto','실감 나게 읽기와 목소리 크기에 대해 바르게 말한 것은 무엇일까요?',ARRAY['K3-1-u2-X26','K3-1-u2-X25','K3-1-u2-X22']::text[],false,'{"seq":20,"concept":"K3-1-u2-C26","difficulty":3,"kind":"mc","stem":"실감 나게 읽기와 목소리 크기에 대해 바르게 말한 것은 무엇일까요?","options":[{"t":"힘찬 장면은 크게, 조용한 장면은 작게 — 장면과 어울리는 크기를 골라요.","correct":true},{"t":"언제나 가장 크게 읽어야 실감 나요.","mis":"K3-1-u2-X26"},{"t":"언제나 가장 작게 읽어야 실감 나요.","mis":"K3-1-u2-X25"},{"t":"크기는 처음 정한 대로 끝까지 지켜요.","mis":"K3-1-u2-X22"}],"explanation":["크기보다","어울림","장면에 맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#21','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C28',3,'mc','auto','발표회 전에 짝과 연습할 때 가장 알맞은 방법은 무엇일까요?',ARRAY['K3-1-u2-X16','K3-1-u2-X28','K3-1-u2-X30']::text[],false,'{"seq":21,"concept":"K3-1-u2-C28","difficulty":3,"kind":"mc","stem":"발표회 전에 짝과 연습할 때 가장 알맞은 방법은 무엇일까요?","options":[{"t":"서로 읽어 주고 ∨ 자리와 빠르기를 함께 살핀다","correct":true},{"t":"누가 더 빨리 읽나 겨룬다","mis":"K3-1-u2-X16"},{"t":"연습 없이 발표회 날 처음 읽는다","mis":"K3-1-u2-X28"},{"t":"짝이 멈춘 곳을 세어 놀린다","mis":"K3-1-u2-X30"}],"explanation":["함께","∨ · 빠르기","연습"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#22','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C13',3,'mc','auto','「가을 운동회」를 친구들 앞에서 읽을 때 배운 것을 모두 살린 읽기는 무엇일까요?',ARRAY['K3-1-u2-X14','K3-1-u2-X12','K3-1-u2-X20']::text[],false,'{"seq":22,"concept":"K3-1-u2-C13","difficulty":3,"kind":"mc","stem":"「가을 운동회」를 친구들 앞에서 읽을 때 배운 것을 모두 살린 읽기는 무엇일까요?","options":[{"t":"∨에서 쉬고, 부호에 맞게, 장면마다 마음을 살려 읽는다","correct":true},{"t":"아무 데서나 쉬며 같은 목소리로 읽는다","mis":"K3-1-u2-X14"},{"t":"낱말마다 끊어 크게만 읽는다","mis":"K3-1-u2-X12"},{"t":"어려운 줄은 건너뛰고 빠르게 읽는다","mis":"K3-1-u2-X20"}],"explanation":["짜임","부호","마음"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#23','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C8',4,'essay','teacher','「우리 반 친구들이 운동회에서 줄을 힘껏 당겼습니다.」를 두 부분으로 나누어 쓰고, 그렇게 나눈 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u2-C8","difficulty":4,"kind":"essay","stem":"「우리 반 친구들이 운동회에서 줄을 힘껏 당겼습니다.」를 두 부분으로 나누어 쓰고, 그렇게 나눈 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리 반 친구들이 / 운동회에서 줄을 힘껏 당겼습니다. 「누가」에 해당하는 「우리 반 친구들이」가 끝나는 곳에서 나누었다.","scoring_points":["두 부분으로 바르게 나누었는가","「누가/무엇이」를 찾았는가","까닭을 썼는가"]},"explanation":["누가","어디까지","나눈 까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#24','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C16',4,'essay','teacher','「가을 운동회」를 알맞은 빠르기로 읽어야 하는 까닭을 너무 빠를 때와 너무 느릴 때를 들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u2-C16","difficulty":4,"kind":"essay","stem":"「가을 운동회」를 알맞은 빠르기로 읽어야 하는 까닭을 너무 빠를 때와 너무 느릴 때를 들어 쓰세요.","answer_guide":{"answer":"예: 너무 빠르면 듣는 사람이 줄다리기 장면을 알아듣기 어렵다. 너무 느리면 뚝뚝 끊겨 힘찬 느낌이 사라진다. 그래서 듣는 사람이 편하게 알아듣는 빠르기로 읽어야 한다.","scoring_points":["너무 빠를 때를 썼는가","너무 느릴 때를 썼는가","알맞은 빠르기로 읽어야 하는 까닭을 썼는가"]},"explanation":["빠르면","느리면","알맞게"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_b#25','kor',3,1,'u2','','g3_1_kor_u2_review_b','unit_review','K3-1-u2-C30',4,'essay','teacher','친구가 「가을 운동회」를 읽고 난 뒤 해 줄 칭찬 한 가지와 도움말 한 가지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u2-C30","difficulty":4,"kind":"essay","stem":"친구가 「가을 운동회」를 읽고 난 뒤 해 줄 칭찬 한 가지와 도움말 한 가지를 쓰세요.","answer_guide":{"answer":"예: 칭찬 — 「영차 부분을 줄을 당기는 몸짓과 함께 힘차게 읽어서 정말 줄다리기를 하는 것 같았어.」 / 도움말 — 「청군 친구의 말은 조금 더 작고 느리게 읽으면 더 좋겠어.」","scoring_points":["칭찬을 썼는가","도움말을 하나만 부드럽게 썼는가","친구를 배려하는 말인가"]},"explanation":["칭찬","도움말 하나","배려"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#1','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C6',1,'mc','auto','「가을 운동회」의 「하늘이 맑습니다.」의 뒷부분은 무엇을 나타낼까요?',ARRAY['K3-1-u2-X06','K3-1-u2-X07','K3-1-u2-X09']::text[],false,'{"seq":1,"concept":"K3-1-u2-C6","difficulty":1,"kind":"mc","stem":"「가을 운동회」의 「하늘이 맑습니다.」의 뒷부분은 무엇을 나타낼까요?","options":[{"t":"상태 — 어떠하다","correct":true},{"t":"움직임 — 어찌하다","mis":"K3-1-u2-X06"},{"t":"무엇인지 — 무엇이다","mis":"K3-1-u2-X07"},{"t":"누가 — 문장의 앞부분","mis":"K3-1-u2-X09"}],"explanation":["맑음","상태","어떠하다"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#2','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C4',1,'mc','auto','「힘껏 외쳤습니다.」만 있으면 알 수 없는 것은 무엇일까요?',ARRAY['K3-1-u2-X04','K3-1-u2-X10','K3-1-u2-X09']::text[],false,'{"seq":2,"concept":"K3-1-u2-C4","difficulty":1,"kind":"mc","stem":"「힘껏 외쳤습니다.」만 있으면 알 수 없는 것은 무엇일까요?","options":[{"t":"누가 외쳤는지","correct":true},{"t":"아무것도 없어요","mis":"K3-1-u2-X04"},{"t":"외친 낱말의 글자 수만","mis":"K3-1-u2-X10"},{"t":"뒷부분이 무엇인지","mis":"K3-1-u2-X09"}],"explanation":["누가","외쳤나요?","앞부분"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#3','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C12',1,'mc','auto','「도윤이는 백군입니다.」를 바르게 띄어 읽은 것은 무엇일까요?',ARRAY['K3-1-u2-X11','K3-1-u2-X12']::text[],false,'{"seq":3,"concept":"K3-1-u2-C12","difficulty":1,"kind":"mc","stem":"「도윤이는 백군입니다.」를 바르게 띄어 읽은 것은 무엇일까요?","options":[{"t":"도윤이는 ∨ 백군입니다.","correct":true},{"t":"도윤 ∨ 이는 백군입니다.","mis":"K3-1-u2-X11"},{"t":"도윤이는 백군 ∨ 입니다.","mis":"K3-1-u2-X11"},{"t":"도 ∨ 윤 ∨ 이는 ∨ 백군입니다.","mis":"K3-1-u2-X12"}],"explanation":["누가?","도윤이는","다음에 ∨"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
