INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#9','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C5',2,'mc','auto','「가을 운동회」에서 뒷부분이 「어찌하다」인 문장은 무엇일까요?',ARRAY['K3-1-u2-X06','K3-1-u2-X08']::text[],false,'{"seq":9,"concept":"K3-1-u2-C5","difficulty":2,"kind":"mc","stem":"「가을 운동회」에서 뒷부분이 「어찌하다」인 문장은 무엇일까요?","options":[{"t":"청군과 백군이 줄을 당깁니다.","correct":true},{"t":"하늘이 맑습니다.","mis":"K3-1-u2-X06"},{"t":"도윤이는 백군입니다.","mis":"K3-1-u2-X08"},{"t":"줄이 아주 굵습니다.","mis":"K3-1-u2-X06"}],"explanation":["당기기","움직임","어찌하다"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#10','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C9',2,'mc','auto','「운동회가 열렸고 하늘이 맑았고 줄을 당겼고 아이들이 외쳤고 우리가 이겼고 신났다.」를 고치는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X10','K3-1-u2-X04']::text[],false,'{"seq":10,"concept":"K3-1-u2-C9","difficulty":2,"kind":"mc","stem":"「운동회가 열렸고 하늘이 맑았고 줄을 당겼고 아이들이 외쳤고 우리가 이겼고 신났다.」를 고치는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"두 부분이 또렷한 짧은 문장 여러 개로 나누어 쓴다","correct":true},{"t":"더 길게 이어 붙인다","mis":"K3-1-u2-X10"},{"t":"「누가/무엇이」를 모두 지운다","mis":"K3-1-u2-X04"},{"t":"지금 그대로가 가장 좋다","mis":"K3-1-u2-X10"}],"explanation":["길게?","짧고 또렷하게","나누어 쓰기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#11','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C10',2,'mc','auto','「줄이 백군 쪽으로 조금씩 끌려왔습니다.」에 ∨를 하나 둔다면 어디가 알맞을까요?',ARRAY['K3-1-u2-X11','K3-1-u2-X12']::text[],false,'{"seq":11,"concept":"K3-1-u2-C10","difficulty":2,"kind":"mc","stem":"「줄이 백군 쪽으로 조금씩 끌려왔습니다.」에 ∨를 하나 둔다면 어디가 알맞을까요?","options":[{"t":"줄이 ∨ 백군 쪽으로 조금씩 끌려왔습니다.","correct":true},{"t":"줄 ∨ 이 백군 쪽으로 조금씩 끌려왔습니다.","mis":"K3-1-u2-X11"},{"t":"줄이 백군 쪽으로 조금씩 끌려왔 ∨ 습니다.","mis":"K3-1-u2-X11"},{"t":"줄 ∨ 이 ∨ 백군 ∨ 쪽으로 ∨ 조금씩 ∨ 끌려왔습니다.","mis":"K3-1-u2-X12"}],"explanation":["무엇이?","줄이","다음에 ∨"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
