INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#15','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C29',2,'mc','auto','발표회에서 잘 읽는 친구만 나가자는 말에 대해 알맞은 생각은 무엇일까요?',ARRAY['K3-1-u2-X29','K3-1-u2-X30','K3-1-u2-X28']::text[],false,'{"seq":15,"concept":"K3-1-u2-C29","difficulty":2,"kind":"mc","stem":"발표회에서 잘 읽는 친구만 나가자는 말에 대해 알맞은 생각은 무엇일까요?","options":[{"t":"저마다 고른 글을 읽어 즐거움을 나누는 자리이니 모두 나가요.","correct":true},{"t":"맞아요, 겨루기니까 잘하는 사람만 나가요.","mis":"K3-1-u2-X29"},{"t":"못 읽는 친구는 듣기만 하고 놀려도 돼요.","mis":"K3-1-u2-X30"},{"t":"준비도 필요 없어요.","mis":"K3-1-u2-X28"}],"explanation":["나눔","모두","함께"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
