INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#17','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C6',3,'mc','auto','뒷부분이 모두 「어떠하다」인 것끼리 모은 것은 무엇일까요?',ARRAY['K3-1-u2-X06','K3-1-u2-X07']::text[],false,'{"seq":17,"concept":"K3-1-u2-C6","difficulty":3,"kind":"mc","stem":"뒷부분이 모두 「어떠하다」인 것끼리 모은 것은 무엇일까요?","options":[{"t":"작습니다 · 차갑습니다 · 넓습니다","correct":true},{"t":"달립니다 · 웃습니다 · 넓습니다","mis":"K3-1-u2-X06"},{"t":"학생입니다 · 작습니다 · 차갑습니다","mis":"K3-1-u2-X07"},{"t":"뜁니다 · 노래합니다 · 먹습니다","mis":"K3-1-u2-X06"}],"explanation":["모두","상태","어떠하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
