INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#19','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C19',3,'mc','auto','「가을 운동회」를 읽을 때 뜻을 생각한 읽기로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X21','K3-1-u2-X16','K3-1-u2-X20']::text[],false,'{"seq":19,"concept":"K3-1-u2-C19","difficulty":3,"kind":"mc","stem":"「가을 운동회」를 읽을 때 뜻을 생각한 읽기로 가장 알맞은 것은 무엇일까요?","options":[{"t":"「영차, 영차!」는 힘차게, 「이겼다!」는 기쁘게 살려 읽는다","correct":true},{"t":"모든 줄을 같은 빠르기 · 같은 크기로 읽는다","mis":"K3-1-u2-X21"},{"t":"뜻은 생각하지 않고 빠르게 끝낸다","mis":"K3-1-u2-X16"},{"t":"어려운 줄은 건너뛴다","mis":"K3-1-u2-X20"}],"explanation":["뜻을 생각하면","살려 읽을 곳","보여요"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#20','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C24',3,'mc','auto','「아쉽다….」 하며 고개를 떨군 청군 친구의 말을 읽는 방법으로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X25','K3-1-u2-X26','K3-1-u2-X22']::text[],false,'{"seq":20,"concept":"K3-1-u2-C24","difficulty":3,"kind":"mc","stem":"「아쉽다….」 하며 고개를 떨군 청군 친구의 말을 읽는 방법으로 알맞은 것은 무엇일까요?","options":[{"t":"작고 느린 목소리로, 고개를 조금 숙이며 읽는다","correct":true},{"t":"밝고 높은 목소리로 손뼉을 치며 읽는다","mis":"K3-1-u2-X25"},{"t":"크게 소리치며 읽는다","mis":"K3-1-u2-X26"},{"t":"아무 표정 없이 빠르게 읽는다","mis":"K3-1-u2-X22"}],"explanation":["아쉬움","작고 느리게","고개 숙이기"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#21','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C31',3,'mc','auto','단원을 마친 뒤 「배운 것은 이제 끝이야.」라고 말한 친구에게 해 줄 말로 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X31','K3-1-u2-X29']::text[],false,'{"seq":21,"concept":"K3-1-u2-C31","difficulty":3,"kind":"mc","stem":"단원을 마친 뒤 「배운 것은 이제 끝이야.」라고 말한 친구에게 해 줄 말로 알맞은 것은 무엇일까요?","options":[{"t":"「책을 읽거나 발표할 때마다 날마다 쓰는 힘이야.」","correct":true},{"t":"「맞아, 이제 웅얼거려도 돼.」","mis":"K3-1-u2-X31"},{"t":"「발표회 날에만 쓰면 돼.」","mis":"K3-1-u2-X31"},{"t":"「잘 읽는 사람만 쓰는 거야.」","mis":"K3-1-u2-X29"}],"explanation":["단원이 끝나도","날마다","이어 가기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#22','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C19',3,'mc','auto','같은 글이라도 뜻을 생각하며 읽으면 무엇이 달라질까요?',ARRAY['K3-1-u2-X21','K3-1-u2-X16','K3-1-u2-X20']::text[],false,'{"seq":22,"concept":"K3-1-u2-C19","difficulty":3,"kind":"mc","stem":"같은 글이라도 뜻을 생각하며 읽으면 무엇이 달라질까요?","options":[{"t":"쉬고 힘줄 곳을 알아 듣는 사람에게 뜻이 잘 전해진다","correct":true},{"t":"아무것도 달라지지 않는다","mis":"K3-1-u2-X21"},{"t":"빨리 읽을 수 있어 좋다","mis":"K3-1-u2-X16"},{"t":"모르는 낱말을 건너뛸 수 있다","mis":"K3-1-u2-X20"}],"explanation":["뜻을 알면","쉬고 힘줄 곳","잘 전해져요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#23','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C14',4,'essay','teacher','운동회 날 내가 한 일을 「누가/무엇이 + 어찌하다」 짜임의 문장 두 개로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u2-C14","difficulty":4,"kind":"essay","stem":"운동회 날 내가 한 일을 「누가/무엇이 + 어찌하다」 짜임의 문장 두 개로 쓰세요.","answer_guide":{"answer":"예: 나는 이어달리기를 했습니다. 우리 반 친구들이 큰 소리로 응원했습니다.","scoring_points":["두 문장을 썼는가","두 문장 모두 두 부분을 갖추었는가","운동회 날의 일과 이어지는가"]},"explanation":["누가","어찌하다","두 문장"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#24','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C24',4,'essay','teacher','「이겼다!」를 실감 나게 읽을 방법을 준언어와 비언어로 나누어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u2-C24","difficulty":4,"kind":"essay","stem":"「이겼다!」를 실감 나게 읽을 방법을 준언어와 비언어로 나누어 쓰세요.","answer_guide":{"answer":"예: 준언어 — 높고 빠르고 힘찬 목소리로 읽는다. 비언어 — 활짝 웃으며 두 팔을 번쩍 든다.","scoring_points":["준언어(목소리)를 썼는가","비언어(표정 · 몸짓)를 썼는가","기쁜 마음과 어울리는가"]},"explanation":["목소리","표정 · 몸짓","기쁜 마음"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_c#25','kor',3,1,'u2','','g3_1_kor_u2_review_c','unit_review','K3-1-u2-C31',4,'essay','teacher','「분명하고 유창하게」에서 배운 것을 생활 속 어느 때에 쓸 수 있는지 두 가지 상황을 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u2-C31","difficulty":4,"kind":"essay","stem":"「분명하고 유창하게」에서 배운 것을 생활 속 어느 때에 쓸 수 있는지 두 가지 상황을 들어 쓰세요.","answer_guide":{"answer":"예: 학급 회의에서 의견을 발표할 때 또박또박 알맞은 빠르기로 말하겠다. 할머니께 동화책을 읽어 드릴 때 인물의 마음을 살려 실감 나게 읽어 드리겠다.","scoring_points":["두 가지 상황을 썼는가","배운 읽기 방법과 이어지는가","실천할 모습이 드러나는가"]},"explanation":["상황 하나","상황 둘","실천"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_d#1','kor',3,1,'u2','','g3_1_kor_u2_review_d','unit_review','K3-1-u2-C7',1,'mc','auto','「가을 운동회」의 「도윤이는 백군입니다.」의 뒷부분은 무엇을 나타낼까요?',ARRAY['K3-1-u2-X08','K3-1-u2-X07','K3-1-u2-X09']::text[],false,'{"seq":1,"concept":"K3-1-u2-C7","difficulty":1,"kind":"mc","stem":"「가을 운동회」의 「도윤이는 백군입니다.」의 뒷부분은 무엇을 나타낼까요?","options":[{"t":"무엇인지 — 무엇이다","correct":true},{"t":"움직임 — 어찌하다","mis":"K3-1-u2-X08"},{"t":"상태 — 어떠하다","mis":"K3-1-u2-X07"},{"t":"누가 — 문장의 앞부분","mis":"K3-1-u2-X09"}],"explanation":["백군입니다","무엇인지","무엇이다"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
