INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_d#21','kor',3,1,'u2','','g3_1_kor_u2_review_d','unit_review','K3-1-u2-C29',3,'mc','auto','발표회에서 차례를 미루는 친구를 돕는 방법으로 가장 알맞은 것은 무엇일까요?',ARRAY['K3-1-u2-X29','K3-1-u2-X30','K3-1-u2-X28']::text[],false,'{"seq":21,"concept":"K3-1-u2-C29","difficulty":3,"kind":"mc","stem":"발표회에서 차례를 미루는 친구를 돕는 방법으로 가장 알맞은 것은 무엇일까요?","options":[{"t":"짝 앞에서 한 줄 읽기부터 함께 해 본다","correct":true},{"t":"잘 읽는 친구만 나가게 한다","mis":"K3-1-u2-X29"},{"t":"못 읽으면 웃자고 한다","mis":"K3-1-u2-X30"},{"t":"연습 없이 그냥 내보낸다","mis":"K3-1-u2-X28"}],"explanation":["작게","함께","시작하기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_d#22','kor',3,1,'u2','','g3_1_kor_u2_review_d','unit_review','K3-1-u2-C32',3,'mc','auto','「하늘이 깡충깡충 뜁니다.」를 뜻이 통하게 바르게 고친 것은 무엇일까요?',ARRAY['K3-1-u2-X05','K3-1-u2-X04']::text[],false,'{"seq":22,"concept":"K3-1-u2-C32","difficulty":3,"kind":"mc","stem":"「하늘이 깡충깡충 뜁니다.」를 뜻이 통하게 바르게 고친 것은 무엇일까요?","options":[{"t":"토끼가 깡충깡충 뜁니다.","correct":true},{"t":"하늘이 깡충깡충 맛있습니다.","mis":"K3-1-u2-X05"},{"t":"깡충깡충 뜁니다.","mis":"K3-1-u2-X04"},{"t":"하늘이 깡충깡충 학생입니다.","mis":"K3-1-u2-X05"}],"explanation":["누가","뛰나요?","뜻이 통하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_d#23','kor',3,1,'u2','','g3_1_kor_u2_review_d','unit_review','K3-1-u2-C10',4,'essay','teacher','「가을 운동회」에서 두 문장을 골라 ∨와 ∨∨를 알맞게 표시해 옮겨 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K3-1-u2-C10","difficulty":4,"kind":"essay","stem":"「가을 운동회」에서 두 문장을 골라 ∨와 ∨∨를 알맞게 표시해 옮겨 쓰세요.","answer_guide":{"answer":"예: 청군과 백군이 ∨ 줄을 당깁니다. ∨∨ 도윤이는 ∨ 백군입니다. ∨∨","scoring_points":["두 문장을 옮겨 썼는가","「누가/무엇이」 다음에 ∨를 두었는가","문장 끝에 ∨∨를 두었는가"]},"explanation":["∨","∨∨","바른 자리"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_d#24','kor',3,1,'u2','','g3_1_kor_u2_review_d','unit_review','K3-1-u2-C21',4,'essay','teacher','「가을 운동회」에서 도윤이와 청군 친구의 마음을 각각 짐작하고, 그렇게 짐작한 근거를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-1-u2-C21","difficulty":4,"kind":"essay","stem":"「가을 운동회」에서 도윤이와 청군 친구의 마음을 각각 짐작하고, 그렇게 짐작한 근거를 쓰세요.","answer_guide":{"answer":"예: 도윤이는 「이겼다!」 하며 두 팔을 번쩍 들었으니 기쁜 마음이다. 청군 친구는 「아쉽다….」 하며 고개를 떨구었으니 아쉬운 마음이다.","scoring_points":["도윤이의 마음을 썼는가","청군 친구의 마음을 썼는가","인물의 말이나 행동을 근거로 들었는가"]},"explanation":["도윤","청군 친구","근거"],"asset":{"type":"passage","lines":["가을 운동회가 열렸습니다.","하늘이 맑습니다.","청군과 백군이 줄을 당깁니다.","도윤이는 백군입니다.","「영차, 영차!」 아이들이 힘껏 외쳤습니다.","줄이 백군 쪽으로 조금씩 끌려왔습니다.","「이겼다!」 도윤이가 두 팔을 번쩍 들었습니다.","청군 친구는 「아쉽다….」 하며 고개를 떨구었습니다."],"title":"가을 운동회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_kor_u2_review_d#25','kor',3,1,'u2','','g3_1_kor_u2_review_d','unit_review','K3-1-u2-C1',4,'essay','teacher','「분명하고 유창하게」에서 배운 세 가지를 한 문장씩 정리해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-1-u2-C1","difficulty":4,"kind":"essay","stem":"「분명하고 유창하게」에서 배운 세 가지를 한 문장씩 정리해 쓰세요.","answer_guide":{"answer":"예: 문장은 「누가/무엇이」와 「어찌하다 · 어떠하다 · 무엇이다」로 이루어지고, 「누가/무엇이」 다음에서 쉬어 읽는다. 글은 뜻을 생각하며 알맞은 빠르기로 부호에 맞게 유창하게 읽는다. 이야기는 인물의 마음을 짐작해 목소리 · 표정 · 몸짓으로 실감 나게 읽는다.","scoring_points":["문장의 짜임을 정리했는가","유창하게 읽기를 정리했는가","실감 나게 읽기를 정리했는가"]},"explanation":["짜임","유창","실감"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
